// --- absolute #include paths / cpp warnings not failing preprocessing ---
// Both hit loading the real secure/SimulEfun/SimulEfun.c, which #includes
// ~50 other files by absolute mudlib path and pulls in a header
// (debug.h) that trips a real (harmless) cpp warning.

static void testAbsoluteIncludePathResolvesAgainstMudlibRoot() {
    ObjectVarHarness harness;

    harness.writeFile("/helper_defs.c",
        "int helper() {\n"
        "    return 42;\n"
        "}\n");

    harness.writeFile("/main_with_include.c",
        "#include \"/helper_defs.c\"\n"
        "int probe() {\n"
        "    return helper();\n"
        "}\n");

    auto obj = harness.objects.cloneObject("/main_with_include");
    assert(obj != nullptr);

    amlp::Value result = harness.vm.callFunction(obj, "probe", {});
    assert(std::holds_alternative<int64_t>(result.data));
    assert(std::get<int64_t>(result.data) == 42);

    std::cout << "testAbsoluteIncludePathResolvesAgainstMudlibRoot OK\n";
}

// Found live against a real third-party mudlib corpus (row 3.8's TMI-2
// boot attempt): std/object/sec_ob.c's own real "#include
// \"/std/object/prop.c\"" (itself resolved fine by the single-level
// rewrite the test just above covers) contains a further real
// "#include \"/std/object/prop_logic.c\"" of its own -- an absolute
// include nested inside a file reached via another absolute include,
// previously unresolvable (real cpp's own recursive #include expansion
// never ran this driver's own path rewrite a second time, so the nested
// include kept its untouched leading '/' and cpp tried to open it as a
// literal OS-root-absolute path). Two levels deep here, matching the
// real corpus shape exactly (not an arbitrary N for its own sake).
static void testNestedAbsoluteIncludeInsideAnIncludedFileAlsoResolves() {
    ObjectVarHarness harness;

    harness.writeFile("/innermost.c",
        "int innermost() {\n"
        "    return 7;\n"
        "}\n");

    harness.writeFile("/middle.c",
        "#include \"/innermost.c\"\n"
        "int middle() {\n"
        "    return innermost() + 1;\n"
        "}\n");

    harness.writeFile("/outer.c",
        "#include \"/middle.c\"\n"
        "int probe() {\n"
        "    return middle() + 1;\n"
        "}\n");

    auto obj = harness.objects.cloneObject("/outer");
    assert(obj != nullptr);

    amlp::Value result = harness.vm.callFunction(obj, "probe", {});
    assert(std::holds_alternative<int64_t>(result.data));
    assert(std::get<int64_t>(result.data) == 9); // 7 + 1 + 1

    std::cout << "testNestedAbsoluteIncludeInsideAnIncludedFileAlsoResolves OK\n";
}

// Found live against a real third-party mudlib corpus (Dead Souls 3.8.2's
// boot attempt): real C's own "computed include" form (C99/C11
// 6.10.2p4) -- secure/include/global.h's own real "#define CONFIG_H
// \"/secure/include/config.h\"" followed a few lines later by "#include
// CONFIG_H", a bare macro name with no '<' or '"' of its own on the
// '#include' line at all. The absolute-include text scan the two tests
// just above cover only ever looks for a literal '"' character on the
// '#include' line itself, so a macro-computed one passed through
// completely untouched; real system cpp then expanded the macro
// *internally* and tried to open the real absolute path against the
// actual host filesystem root, "No such file or directory" -- blocking
// this mudlib's own global_include_file from compiling at all, which in
// turn blocked *every single object* in the mudlib (global_include_file
// is implicitly #included into everything). Mirrors the real shape
// exactly: the macro is #define'd earlier in the same file as its own
// later, bare-name '#include'.
static void testMacroComputedAbsoluteIncludeResolvesAgainstMudlibRoot() {
    ObjectVarHarness harness;

    harness.writeFile("/config_target.c",
        "int config_value() {\n"
        "    return 99;\n"
        "}\n");

    harness.writeFile("/global_with_computed_include.c",
        "#define CONFIG_H \"/config_target.c\"\n"
        "#include CONFIG_H\n"
        "int probe() {\n"
        "    return config_value();\n"
        "}\n");

    auto obj = harness.objects.cloneObject("/global_with_computed_include");
    assert(obj != nullptr);

    amlp::Value result = harness.vm.callFunction(obj, "probe", {});
    assert(std::holds_alternative<int64_t>(result.data));
    assert(std::get<int64_t>(result.data) == 99);

    std::cout << "testMacroComputedAbsoluteIncludeResolvesAgainstMudlibRoot OK\n";
}

// Real FluffOS's own driver-internal "#if efun_defined(name)"/"#elif
// efun_defined(name)" (distinct from the standard cpp "defined(name)"),
// confirmed directly against Dead Souls 3.8.2's own bundled
// fluffos-2.23-ds03/lex.c:3040. This driver shells out to real,
// unmodified system cpp, which has no knowledge of this driver-specific
// construct at all -- system cpp's own real "#if" constant-expression
// evaluator defaults the bare, unexpanded "efun_defined" identifier to
// 0 (real C99 6.10.1p4), immediately followed by "(", producing a real
// "missing binary operator before token '('" error. Real corpus: Dead
// Souls 3.8.2's own secure/sefun/sefun.c's real "#if
// efun_defined(query_charmode)" blocked that file (this mudlib's own
// configured simul_efun file) from compiling at all. Exercises both
// real outcomes: a genuinely-registered efun name compiles the guarded
// branch in, an unregistered one compiles the "#else" branch instead --
// proving this is a real, live query against the injected checker, not
// a stub that always answers one way.
static void testEfunDefinedInIfDirectiveResolvesAgainstTheInjectedEfunChecker() {
    ObjectVarHarness harness;
    harness.objects.setEfunExistsChecker([](const std::string& name) {
        return name == "a_real_registered_efun";
    });

    harness.writeFile("/efun_defined_probe.c",
        "int probe() {\n"
        "#if efun_defined(a_real_registered_efun)\n"
        "    return 1;\n"
        "#else\n"
        "    return 0;\n"
        "#endif\n"
        "}\n"
        "int probe_missing() {\n"
        "#if efun_defined(some_totally_made_up_efun_name)\n"
        "    return 1;\n"
        "#else\n"
        "    return 0;\n"
        "#endif\n"
        "}\n");

    auto obj = harness.objects.cloneObject("/efun_defined_probe");
    assert(obj != nullptr);

    amlp::Value registered = harness.vm.callFunction(obj, "probe", {});
    assert(std::holds_alternative<int64_t>(registered.data));
    assert(std::get<int64_t>(registered.data) == 1);

    amlp::Value missing = harness.vm.callFunction(obj, "probe_missing", {});
    assert(std::holds_alternative<int64_t>(missing.data));
    assert(std::get<int64_t>(missing.data) == 0);

    std::cout << "testEfunDefinedInIfDirectiveResolvesAgainstTheInjectedEfunChecker OK\n";
}

// Found live against the same real Dead Souls 3.8.2 boot attempt, a
// second, distinct bug in the same area: real cpp macro scope is
// whole-compilation, not per-file -- a macro #define'd in one
// #include'd file stays visible for the rest of the compilation unit,
// including the file that #included it and everything after. Real
// corpus: Dead Souls' own configured global include file,
// secure/include/global.h, #defines several macros this way ("#define
// ROOMS_H \"/secure/include/rooms.h\""), each meant to be used later by
// whichever real object file needs it -- secure/daemon/master.c's own
// real "#include ROOMS_H" is *not* inside global.h at all, it is the
// compiled object's own body, several files away from where ROOMS_H was
// actually #define'd. This driver's own global-include-file splice
// (the fix just above) and the compiled object's own body used two
// independent macro-tracking maps, so a macro recorded while resolving
// the global include file was invisible again the moment the real
// object's own body was scanned. Fixed by sharing one macro map (and
// include-cycle-guard set) across both, matching real cpp's own single,
// whole-unit macro scope.
static void testGlobalIncludeFileMacroComputedIncludeIsVisibleInTheCompiledObjectsOwnBody() {
    ObjectVarHarness harness("global_include_file: <global_macros.h>\n");
    harness.writeFile("/global_macros.h",
        "#define ROOMS_H \"/rooms_target.c\"\n");
    harness.writeFile("/rooms_target.c",
        "int rooms_value() {\n"
        "    return 17;\n"
        "}\n");
    harness.writeFile("/uses_global_macro.c",
        "#include ROOMS_H\n"
        "int probe() {\n"
        "    return rooms_value();\n"
        "}\n");

    auto obj = harness.objects.cloneObject("/uses_global_macro");
    assert(obj != nullptr);

    amlp::Value result = harness.vm.callFunction(obj, "probe", {});
    assert(std::holds_alternative<int64_t>(result.data));
    assert(std::get<int64_t>(result.data) == 17);

    std::cout << "testGlobalIncludeFileMacroComputedIncludeIsVisibleInTheCompiledObjectsOwnBody OK\n";
}

// ROADMAP.md row 3.10's own follow-up: the include-rewrite pass
// (rewriteAbsoluteIncludesRecursive()) previously only ever recursed
// into an *absolute* quoted include -- an ordinary relative quoted or
// angle-bracket include was always left for real cpp's own "-I" search
// to resolve blind, with no opportunity for anything inside that file
// to reach this driver's own logic. Real corpus: Dead Souls 3.8.2's
// own secure/include/logs.h, reached from secure/daemon/master.c via
// an entirely ordinary "#include <logs.h>", itself contains a further
// real "#include CONFIG_H" (a macro-computed absolute include) that was
// invisible to this pass entirely until it was made to resolve every
// #include form, not just the two originally special-cased entry
// points. The four tests below cover the generalized recursion itself,
// independent of whether any specific real mudlib boots: a relative
// quoted include reached transitively (proving the new currentDir
// threading resolves against the *including* file's own directory, not
// the outermost file's), an angle-bracket include reached transitively,
// a macro #define'd and consumed entirely within a file reached via an
// ordinary (non-absolute) include, and a real include cycle with a real
// "#ifndef" guard (proving activeIncludes still terminates this
// driver's own splicing correctly, while the overall compile succeeds
// via real cpp's own guard evaluation on the assembled result, the
// exact same way real cpp's own recursive #include handling already
// relies on for a genuinely cyclic, guarded header).

static void testRecursiveIncludeResolvesARelativeQuotedIncludeAgainstItsOwnIncludingFilesDirectory() {
    ObjectVarHarness harness;
    assert(::mkdir((harness.tempDir + "/sub").c_str(), 0755) == 0);

    harness.writeFile("/sub/inner.h", "int mid_value() { return 42; }\n");
    // mid.h's own "#include \"inner.h\"" must resolve against mid.h's
    // *own* directory ("sub/"), not outer.c's (the mudlib root) -- if
    // currentDir were not threaded through the recursion correctly,
    // this would search the root instead and fail to find inner.h at
    // all, since inner.h is never referenced from outer.c directly.
    harness.writeFile("/sub/mid.h", "#include \"inner.h\"\n");
    harness.writeFile("/outer.c",
        "#include \"sub/mid.h\"\n"
        "int probe() { return mid_value(); }\n");

    auto obj = harness.objects.cloneObject("/outer");
    assert(obj != nullptr);
    amlp::Value result = harness.vm.callFunction(obj, "probe", {});
    assert(std::holds_alternative<int64_t>(result.data));
    assert(std::get<int64_t>(result.data) == 42);

    std::cout << "testRecursiveIncludeResolvesARelativeQuotedIncludeAgainstItsOwnIncludingFilesDirectory OK\n";
}

static void testRecursiveIncludeResolvesAnAngleBracketIncludeReachedTransitively() {
    ObjectVarHarness harness;
    harness.writeFile("/level2.h", "int level2_value() { return 84; }\n");
    // level1.h's own "#include <level2.h>" is itself reached only via
    // outer.c's own "#include <level1.h>" -- level2.h was never
    // referenced from outer.c directly, so this only resolves if the
    // pass recurses into level1.h's own content at all.
    harness.writeFile("/level1.h", "#include <level2.h>\n");
    harness.writeFile("/outer.c",
        "#include <level1.h>\n"
        "int probe() { return level2_value(); }\n");

    auto obj = harness.objects.cloneObject("/outer");
    assert(obj != nullptr);
    amlp::Value result = harness.vm.callFunction(obj, "probe", {});
    assert(std::holds_alternative<int64_t>(result.data));
    assert(std::get<int64_t>(result.data) == 84);

    std::cout << "testRecursiveIncludeResolvesAnAngleBracketIncludeReachedTransitively OK\n";
}

static void testRecursiveIncludeResolvesAMacroDefinedAndConsumedEntirelyWithinATransitivelyReachedFile() {
    ObjectVarHarness harness;
    harness.writeFile("/deep_target.c", "int deep_value() { return 55; }\n");
    // mid.h is reached from outer.c via an ordinary relative quoted
    // include (not the outermost file, not the designated global
    // include file -- the two entry points macro tracking already
    // covered before this generalization); mid.h then both #defines
    // and #includes its own macro entirely within itself.
    harness.writeFile("/mid.h",
        "#define DEEP_HDR \"/deep_target.c\"\n"
        "#include DEEP_HDR\n");
    harness.writeFile("/outer.c",
        "#include \"mid.h\"\n"
        "int probe() { return deep_value(); }\n");

    auto obj = harness.objects.cloneObject("/outer");
    assert(obj != nullptr);
    amlp::Value result = harness.vm.callFunction(obj, "probe", {});
    assert(std::holds_alternative<int64_t>(result.data));
    assert(std::get<int64_t>(result.data) == 55);

    std::cout << "testRecursiveIncludeResolvesAMacroDefinedAndConsumedEntirelyWithinATransitivelyReachedFile OK\n";
}

static void testRecursiveIncludeHandlesARealIncludeCycleWithoutInfiniteLooping() {
    ObjectVarHarness harness;
    // A real cycle (a.h includes b.h includes a.h back), each with a
    // real "#ifndef" multiple-inclusion guard -- activeIncludes must
    // stop this driver's own splicing from recursing forever the
    // moment it reaches the second "#include \"a.h\"" (a.h is already
    // mid-splice at that point), leaving that one line as ordinary
    // literal text for real cpp to see; cpp then correctly no-ops it
    // via the already-#defined guard macro, exactly the way real cpp's
    // own recursive #include handling already relies on for any
    // genuinely cyclic, guarded header.
    harness.writeFile("/a.h",
        "#ifndef A_H\n"
        "#define A_H\n"
        "#include \"b.h\"\n"
        "int a_value() { return 1; }\n"
        "#endif\n");
    harness.writeFile("/b.h",
        "#ifndef B_H\n"
        "#define B_H\n"
        "#include \"a.h\"\n"
        "int b_value() { return 2; }\n"
        "#endif\n");
    harness.writeFile("/outer.c",
        "#include \"a.h\"\n"
        "int probe() { return a_value() + b_value(); }\n");

    auto obj = harness.objects.cloneObject("/outer");
    assert(obj != nullptr);
    amlp::Value result = harness.vm.callFunction(obj, "probe", {});
    assert(std::holds_alternative<int64_t>(result.data));
    assert(std::get<int64_t>(result.data) == 3);

    std::cout << "testRecursiveIncludeHandlesARealIncludeCycleWithoutInfiniteLooping OK\n";
}

// Found live against a real third-party mudlib corpus (row 3.8's TMI-2
// boot attempt): std/object/sec_ob.c's own real "inherit
// \"std/object/ob_logic\";" -- no leading '/', a real, valid LPC form
// this driver's own normalizeFilename() previously left untouched,
// producing a malformed concatenation ("mudlibRoot" + "std/object/
// ob_logic.c", missing the path separator entirely) once every other
// caller assumed a leading '/' was already present. Real semantics: an
// object pathname is always mudlib-root-relative whether or not it
// carries a leading '/', both forms name the same real object.
static void testInheritPathWithoutLeadingSlashResolvesSameAsWithOne() {
    ObjectVarHarness harness;

    harness.writeFile("/base.c",
        "int base_value() {\n"
        "    return 5;\n"
        "}\n");

    // No leading '/' on the inherit target -- the real TMI-2 shape.
    harness.writeFile("/child.c",
        "inherit \"base\";\n"
        "int probe() {\n"
        "    return base_value() + 1;\n"
        "}\n");

    auto obj = harness.objects.cloneObject("/child");
    assert(obj != nullptr);

    amlp::Value result = harness.vm.callFunction(obj, "probe", {});
    assert(std::holds_alternative<int64_t>(result.data));
    assert(std::get<int64_t>(result.data) == 6);

    std::cout << "testInheritPathWithoutLeadingSlashResolvesSameAsWithOne OK\n";
}

