static void testForLoopCommaExprChainInInitAndUpdateVmExecution() {
    // Mirrors secure/SimulEfun/misc.c's own
    // "for(i = 0, s = sizeof(stack1); i < s; i++)" shape (two
    // comma-separated expressions in the init clause here; the update
    // clause tests the same chain shape independently).
    amlp::Value result = runProbe(
        "int i, j, sum;\n"
        "sum = 0;\n"
        "for (i = 0, j = 10; i < 3; i = i + 1, j = j - 1) {\n"
        "    sum = sum + j;\n"
        "}\n"
        "return sum;\n");
    assert(std::holds_alternative<int64_t>(result.data));
    assert(std::get<int64_t>(result.data) == 27); // j = 10, 9, 8 while i = 0, 1, 2

    std::cout << "testForLoopCommaExprChainInInitAndUpdateVmExecution OK\n";
}

// Real grammar.y's own "statement: comma_expr ';'" (grammar.y:1055) applies
// to every plain-expression statement, not just a for-loop's own init/
// update clauses (testForLoopCommaExprChainInInitAndUpdateVmExecution
// just above). Real corpus: TMI-2's own real cmds/file/_eval.c ->
// doith()'s "inp[i] = inp[i] + \";\"+ inp[i+1], inp -= ({inp[i+1]});" -- an
// indexed assignment statement followed by a comma-chained plain
// (whole-variable) compound assignment, previously rejected outright
// ("expected \";\" in indexed assignment statement ... got \",\"") since
// the parser's own statement-level IndexAssignStmt/AssignStmt fast paths
// required their terminating ';' immediately after their own first
// element, with no comma-continuation handling at all -- unlike the
// general expression-statement fallback and the for-loop clauses, which
// already went through parseExpr()/parseCommaExprChain() correctly.
// Covers all three statement fast paths this one shared fix touches: an
// indexed assignment chained with a plain compound assignment (the real
// doith() shape), a bare assignment chained with another bare assignment,
// and a general expression statement (a bare call) chained with an
// assignment.
static void testStatementLevelCommaChainAfterIndexedAndPlainAssignmentVmExecution() {
    amlp::Value indexed = runProbe(
        "int *arr;\n"
        "int side;\n"
        "arr = ({ 1, 2, 3 });\n"
        "arr[0] = arr[0] + 10, side = 99;\n"
        "return arr[0] * 1000 + side;\n");
    assert(std::holds_alternative<int64_t>(indexed.data));
    assert(std::get<int64_t>(indexed.data) == 11099); // arr[0] == 11, side == 99

    amlp::Value plainAssign = runProbe(
        "int a, b;\n"
        "a = 1, b = 2;\n"
        "return a * 10 + b;\n");
    assert(std::holds_alternative<int64_t>(plainAssign.data));
    assert(std::get<int64_t>(plainAssign.data) == 12);

    amlp::Value exprStmt = runProbe(
        "int n;\n"
        // A bare call, discarded, chained with an assignment -- exercises
        // the general expression-statement fallback path specifically
        // (one that does not start with "ident =" or "ident[").
        "sizeof( ({ 1, 2, 3 }) ), n = 7;\n"
        "return n;\n");
    assert(std::holds_alternative<int64_t>(exprStmt.data));
    assert(std::get<int64_t>(exprStmt.data) == 7);

    std::cout << "testStatementLevelCommaChainAfterIndexedAndPlainAssignmentVmExecution OK\n";
}

// --- switch -----------------------------------------------------------
// Hit immediately after for-loop comma-expression chains while
// re-attempting the real boot: secure/SimulEfun/alignment.c's own
// "switch(str_class) { case \"monk\": return ...; default: return 1; }".

static void testSwitchParsesToSwitchStmtWithInterleavedLabels() {
    std::string src =
        "void probe() {\n"
        "    switch (x) {\n"
        "        case 1:\n"
        "            write(\"one\");\n"
        "        case 2:\n"
        "            write(\"two\");\n"
        "            break;\n"
        "        default:\n"
        "            write(\"other\");\n"
        "    }\n"
        "}\n";
    amlp::Lexer lexer(src);
    amlp::Parser parser(lexer.tokenize());
    auto program = parser.parseProgram();

    auto& body = program->functions[0]->body->statements;
    auto* sw = dynamic_cast<amlp::SwitchStmt*>(body[0].get());
    assert(sw != nullptr);
    // [case 1, write("one"), case 2, write("two"), break, default, write("other")]
    assert(sw->body.size() == 7);
    auto* case1 = dynamic_cast<amlp::CaseLabel*>(sw->body[0].get());
    assert(case1 != nullptr && case1->value != nullptr);
    auto* defaultLabel = dynamic_cast<amlp::CaseLabel*>(sw->body[5].get());
    assert(defaultLabel != nullptr && defaultLabel->value == nullptr);

    std::cout << "testSwitchParsesToSwitchStmtWithInterleavedLabels OK\n";
}

static void testSwitchRangeCaseLabelParsesWithRangeEndSet() {
    std::string src =
        "void probe() {\n"
        "    switch (x) {\n"
        "        case 1..5:\n"
        "            break;\n"
        "    }\n"
        "}\n";
    amlp::Lexer lexer(src);
    amlp::Parser parser(lexer.tokenize());
    auto program = parser.parseProgram();

    auto& body = program->functions[0]->body->statements;
    auto* switchStmt = dynamic_cast<amlp::SwitchStmt*>(body[0].get());
    assert(switchStmt != nullptr);
    auto* label = dynamic_cast<amlp::CaseLabel*>(switchStmt->body[0].get());
    assert(label != nullptr);
    assert(label->value != nullptr);
    assert(label->rangeEnd != nullptr);

    std::cout << "testSwitchRangeCaseLabelParsesWithRangeEndSet OK\n";
}

// Real grammar.y's own "L_CASE case_label L_RANGE case_label ':'" --
// found live against a real third-party mudlib corpus (row 3.8's TMI-2
// boot attempt): std/user.c's own real "case 2..3:" / "case 4..6:" / ...
// level-tier ladder, previously rejected outright with a deliberate
// "not implemented" parse error. Covers a match at each end of a range
// (inclusive both sides), a genuine miss falling through to default, and
// that an ordinary single-value case right after a range case is
// unaffected by the new codegen path.
static void testSwitchRangeCaseLabelVmExecution() {
    auto runWith = [](int64_t x) {
        return runProbe(
            "int x;\n"
            "x = " + std::to_string(x) + ";\n"
            "switch (x) {\n"
            "    case 2..3: return 100;\n"
            "    case 4..6: return 200;\n"
            "    case 7: return 300;\n"
            "    default: return -1;\n"
            "}\n"
            "return -2;\n");
    };

    amlp::Value low = runWith(2);
    assert(std::holds_alternative<int64_t>(low.data));
    assert(std::get<int64_t>(low.data) == 100); // low end of the range, inclusive

    amlp::Value high = runWith(3);
    assert(std::holds_alternative<int64_t>(high.data));
    assert(std::get<int64_t>(high.data) == 100); // high end of the range, inclusive

    amlp::Value mid = runWith(5);
    assert(std::holds_alternative<int64_t>(mid.data));
    assert(std::get<int64_t>(mid.data) == 200); // second range, unaffected by the first

    amlp::Value plain = runWith(7);
    assert(std::holds_alternative<int64_t>(plain.data));
    assert(std::get<int64_t>(plain.data) == 300); // ordinary single-value case still works

    amlp::Value miss = runWith(10);
    assert(std::holds_alternative<int64_t>(miss.data));
    assert(std::get<int64_t>(miss.data) == -1); // outside every range, falls to default

    std::cout << "testSwitchRangeCaseLabelVmExecution OK\n";
}

static void testSwitchMatchingCaseVmExecution() {
    // Mirrors secure/SimulEfun/alignment.c's own shape, including a
    // string subject and each case returning immediately.
    amlp::Value result = runProbe(
        "string cls;\n"
        "cls = \"cleric\";\n"
        "switch (cls) {\n"
        "    case \"monk\": return 1;\n"
        "    case \"cleric\": return 2;\n"
        "    default: return 3;\n"
        "}\n"
        "return -1;\n");
    assert(std::holds_alternative<int64_t>(result.data));
    assert(std::get<int64_t>(result.data) == 2);

    std::cout << "testSwitchMatchingCaseVmExecution OK\n";
}

