    amlp::Value unsetVar = harness.vm.callFunction(ob, "probe_unset_var", {});
    assert(std::get<int64_t>(unsetVar.data) == 1);

    std::cout << "testIntpTrueOnlyForIntNotStringObjectOrUnsetVariable OK\n";
