// implode()'s function/fold form and non-string skipping in the join
// form -- real func_spec.c:76 (mixed implode(mixed *, string | function,
// void | mixed)), real efuns_main.c f_implode() dispatching to
// array.c:395 implode_string() (join) or array.c:428 implode_array()
// (left fold). Every expected value traced by hand from those and
// cross-checked against temp/lil/single/tests/efuns/implode.c's own
// assertions.
static void testImplodeFunctionFoldFormAndNonStringSkipping() {
    // Join form: non-string elements are skipped, not stringified and not
    // an error; the separator falls only between consecutive strings; an
    // array with no string element yields "".
    assert(std::get<std::string>(
        runProbe("return implode(({ 1, 2, 3 }), \"foo\");\n").data) == "");
    assert(std::get<std::string>(
        runProbe("return implode(({ 1, \"foo\", \"bar\" }), \"bazz\");\n").data) == "foobazzbar");
    assert(std::get<std::string>(
        runProbe("return implode(({ \"foo\", \"bar\" }), \"\");\n").data) == "foobar");

    // Fold form, no seed: acc = arr[0], then acc = f(acc, elem) for the rest.
    assert(std::get<int64_t>(
        runProbe("return implode(({ 1, 2, 3 }), (: $1 + $2 :));\n").data) == 6);
    // Fold form with a seed: acc = seed, then folded over every element
    // ("" + 1 -> "1", "1" + 2 -> "12", "12" + 3 -> "123").
    assert(std::get<std::string>(
        runProbe("return implode(({ 1, 2, 3 }), (: $1 + $2 :), \"\");\n").data) == "123");
    // Empty array: the seed is returned unchanged; with no seed, int 0.
    assert(std::get<int64_t>(
        runProbe("return implode(({}), (: $1 :), 666);\n").data) == 666);
    assert(std::get<int64_t>(
        runProbe("return implode(({}), (: $1 :));\n").data) == 0);
    // One-element array, no seed: that element unchanged, f never called.
    assert(std::get<int64_t>(
        runProbe("return implode(({ 555 }), (: $1 + 5 :));\n").data) == 555);

    // A 3rd argument alongside a string separator is an error.
    bool threw = false;
    try {
        runProbe("return implode(({ \"a\" }), \",\", \"x\");\n");
    } catch (const std::exception&) {
        threw = true;
    }
    assert(threw);

    std::cout << "testImplodeFunctionFoldFormAndNonStringSkipping OK\n";
}

// sprintf's "%c" -- surfaced live: daemon/terminal.c's own ANSI(p)/ESC(p)
// macros, "sprintf(\"%c[\"+(p)+\"m\", 27)", building a raw ESC (ASCII 27)
// byte ahead of an ANSI escape sequence. Confirmed against
// fluffos-2.9-ds2.08/sprintf.c: INFO_T_CHAR requires a T_NUMBER (int)
// argument, not a string.
static void testSprintfPercentCEmitsSingleCharacterFromIntArgument() {
    amlp::Value result = runProbe("return sprintf(\"%c[31m\", 27);\n");
    assert(std::holds_alternative<std::string>(result.data));
    std::string expected;
    expected += static_cast<char>(27);
    expected += "[31m";
    assert(std::get<std::string>(result.data) == expected);
    std::cout << "testSprintfPercentCEmitsSingleCharacterFromIntArgument OK\n";
}

static void testSprintfPercentCThrowsOnNonIntArgument() {
    bool threw = false;
    try {
        runProbe("return sprintf(\"%c\", \"x\");\n");
    } catch (const amlp::LpcRuntimeError&) {
        threw = true;
    }
    assert(threw);
    std::cout << "testSprintfPercentCThrowsOnNonIntArgument OK\n";
}

// Row 3.9's own finished trace (ROADMAP.md): real sprintf.c's own %d/%o/
// %x/%c type check tests carg->type != T_NUMBER (sprintf.c:1180), and
// real T_UNDEFINED -- the subtype real find_in_mapping() (mapping.c)
// stamps on const0u, the value it returns for a missing, non-column
// mapping[key] lookup -- is a *subtype* of T_NUMBER (lpc.h: "#define
// T_UNDEFINED 0x4"), confirmed directly against main.c's own
// "const0u.subtype = T_UNDEFINED;", not a distinct top-level type. So a
// missing-mapping-key value is real, genuine T_NUMBER at the C level and
// passes real sprintf()'s own %d/%o/%x/%c check, printing as plain 0 --
// exactly like it already passes this driver's own existing
// asArithmeticOperand()/formatNumberForConcat() (VM.cpp) for +/-/* and
// string+number concatenation. This driver's own monostate is this
// driver's T_UNDEFINED-equivalent (see those two functions' own
// comments); before this row's fix, sprintf's own %d/%o/%x/%c instead
// hard-rejected it exactly like a genuinely non-numeric value
// (string/array/mapping/object/closure) -- a real driver-side gap, not
// a mudlib bug, found finishing the trace row 3.9's own prior session
// left open (AetherMUD's cmds/mortal/_score.c::show_experience(), via
// std/living.c's own query_exp(): "player_data[\"general\"][\"experience\"]"
// on a freshly created character whose experience key has never been
// written).
static void testSprintfPercentDThrowsOnNonIntArgument() {
    bool threw = false;
    try {
        runProbe("return sprintf(\"%d\", \"x\");\n");
    } catch (const amlp::LpcRuntimeError&) {
        threw = true;
    }
    assert(threw);
    std::cout << "testSprintfPercentDThrowsOnNonIntArgument OK\n";
}

