static void testOriginReturnsDriverForTopLevelDispatchHeartBeatAndCommandDispatch() {
    ObjectVarHarness harness;
    amlp::Scheduler scheduler(harness.vm);
    harness.vm.setScheduler(&scheduler);
    harness.writeFile("/origin_driver.c",
        "string hb_result;\n"
        "string cmd_result;\n"
        "void setup() { enable_commands(); add_action(\"cmd_go\", \"go\"); }\n"
        "void enable_hb() { set_heart_beat(1); }\n"
        "string probe() { return origin(); }\n"
        "void heart_beat() { hb_result = origin(); }\n"
        "string query_hb() { return hb_result; }\n"
        "int cmd_go(string arg) { cmd_result = origin(); return 1; }\n"
        "string query_cmd() { return cmd_result; }\n");
    auto ob = harness.objects.cloneObject("/origin_driver");
    assert(ob != nullptr);

    // add_action() only registers correctly from inside a command-giver-
    // resolvable context -- resolveCommandGiver() (EfunTable.cpp) falls
    // back to OutputContext::current()'s own bound object when
    // VM::commandGiver()'s explicit stack is empty, so a bare setup()
    // call with no active Connection/OutputContext silently registers
    // nothing (real add_action()'s own documented no-op-outside-context
    // behavior). Matches the exact working pattern the
    // query_notify_fail test suite already establishes: a real
    // Connection, OutputContext::set() around setup(), and dispatch
    // through Server::dispatchLine() rather than VM::dispatchCommand()
    // directly.
    int fds[2];
    assert(::socketpair(AF_UNIX, SOCK_STREAM, 0, fds) == 0);
    amlp::Connection conn(fds[0]);
    conn.attach(ob);
    amlp::OutputContext::set(&conn);
    harness.vm.callFunction(ob, "setup", {});

    // (a) VM::callFunction()'s own default -- real logon()/create()/
    // process_input()/net_dead()/window_size()/every master apply all
    // confirmed real ORIGIN_DRIVER, this is the shared entry point all
    // of them go through.
    amlp::Value direct = harness.vm.callFunction(ob, "probe", {});
    assert(std::holds_alternative<std::string>(direct.data));
    assert(std::get<std::string>(direct.data) == "driver");

    // (b) heart_beat firing -- real backend.c's own "call_direct(ob,
    // ..., ORIGIN_DRIVER, 0)". set_heart_beat() is a core efun, called
    // from within LPC (enable_hb()), the same "bare call from the
    // object's own code" shape the existing set_heart_beat test suite
    // already establishes -- not something to invoke directly through
    // VM::callFunction() by name, which would just silently no-op
    // against a nonexistent "set_heart_beat" *local* function.
    harness.vm.callFunction(ob, "enable_hb", {});
    scheduler.tickHeartbeats();
    amlp::Value hb = harness.vm.callFunction(ob, "query_hb", {});
    assert(std::holds_alternative<std::string>(hb.data));
    assert(std::get<std::string>(hb.data) == "driver");

    // (c) top-level command dispatch, the real entry point (real
    // process_input()/parse_command() from a freshly typed line, this
    // driver's own Server::dispatchLine() -> VM::dispatchCommand(),
    // reached with no LPC frame already active, current_object null) --
    // real add_action.c's own "where = (current_object ? ORIGIN_EFUN :
    // ORIGIN_DRIVER);" resolves to the driver half here.
    amlp::Server::dispatchLine(harness.vm, conn, "go");
    amlp::OutputContext::set(nullptr);
    amlp::Value cmd = harness.vm.callFunction(ob, "query_cmd", {});
    assert(std::holds_alternative<std::string>(cmd.data));
    assert(std::get<std::string>(cmd.data) == "driver");
    ::close(fds[1]);

    std::cout << "testOriginReturnsDriverForTopLevelDispatchHeartBeatAndCommandDispatch OK\n";
}

static void testOriginNameCoversAllEightRealValuesIncludingTheUnreachableFunctionPointer() {
    // Direct C++-level check of the string table itself (real
    // origin_name()'s own "driver"/"local"/"call_other"/"simul"/
    // "internal"/"efun"/"function pointer"/"functional"), including
    // Origin::FunctionPointer -- verified unreachable from any genuine
    // LPC call path in this driver (see Origin's own VM.hpp comment for
    // the full real-semantics citation for why), so this is the only
    // way to confirm origin_name() would still report it correctly if
    // something unexpected ever did reach it.
    assert(std::string(amlp::originName(amlp::Origin::Driver)) == "driver");
    assert(std::string(amlp::originName(amlp::Origin::Local)) == "local");
    assert(std::string(amlp::originName(amlp::Origin::CallOther)) == "call_other");
    assert(std::string(amlp::originName(amlp::Origin::SimulEfun)) == "simul");
    assert(std::string(amlp::originName(amlp::Origin::Internal)) == "internal");
    assert(std::string(amlp::originName(amlp::Origin::Efun)) == "efun");
    assert(std::string(amlp::originName(amlp::Origin::FunctionPointer)) == "function pointer");
    assert(std::string(amlp::originName(amlp::Origin::Functional)) == "functional");

    std::cout << "testOriginNameCoversAllEightRealValuesIncludingTheUnreachableFunctionPointer OK\n";
}

// reload_object(): real object.c's own reload_object(), resetting an
// object back to a freshly-cloned-looking state in place. Verified
// against reference source in full before writing anything (see
// EfunTable.cpp's own registration comment for the complete citation);
// zero real call sites across all six of this row's mudlib corpora,
// re-confirmed fresh rather than assumed unchanged. Each test below
// targets one real, distinct piece of its behavior rather than one
// broad smoke test.

static void testReloadObjectResetsVariablesReinitializesAndCallsCreateAgain() {
    ObjectVarHarness harness;
    harness.writeFile("/reload_core.c",
        "int plain;\n"
        "int initialized = 5;\n"
        "int create_count;\n"
        "void create() { create_count = create_count + 1; }\n"
        "void set_plain(int v) { plain = v; }\n"
        "void set_initialized(int v) { initialized = v; }\n"
        "int get_plain() { return plain; }\n"
        "int get_initialized() { return initialized; }\n"
        "int get_create_count() { return create_count; }\n"
        "void set_create_count(int v) { create_count = v; }\n");
    auto ob = harness.objects.cloneObject("/reload_core");
    assert(ob != nullptr);

    // Sanity: the fresh clone's own create() already ran once, and the
    // real initializer already applied once.
    assert(std::get<int64_t>(harness.vm.callFunction(ob, "get_create_count", {}).data) == 1);
    assert(std::get<int64_t>(harness.vm.callFunction(ob, "get_initialized", {}).data) == 5);

    harness.vm.callFunction(ob, "set_plain", {amlp::Value(int64_t{42})});
    harness.vm.callFunction(ob, "set_initialized", {amlp::Value(int64_t{99})});
    // create_count is itself an ordinary object variable, so it is
    // subject to the exact same zero-then-reinit step everything else
    // is -- it cannot be used to count *across* a reload by simply
    // expecting it to keep incrementing (a real reload_object() zeroes
    // it right along with everything else, the same fresh-slate
    // guarantee that makes this whole efun meaningful in the first
    // place). Corrupted to an arbitrary value here instead, specifically
    // so "did create() genuinely run again" can still be told apart from
    // "create() was skipped": skipped would leave it at 0 (the zero
    // step's own result), genuinely re-run leaves it at 1.
    harness.vm.callFunction(ob, "set_create_count", {amlp::Value(int64_t{777})});
    assert(std::get<int64_t>(harness.vm.callFunction(ob, "get_plain", {}).data) == 42);
    assert(std::get<int64_t>(harness.vm.callFunction(ob, "get_initialized", {}).data) == 99);

    std::vector<amlp::Value> reloadArgs{amlp::Value(ob)};
    amlp::EfunTable::instance().call("reload_object", harness.vm, reloadArgs);

    // plain has no initializer -- zeroed, and create() does not set it,
    // so it stays 0. initialized has a real initializer -- zeroed, then
    // the real re-run "$objvarinit" puts it straight back to 5, not 0
    // and not the 99 it was overwritten to (real call_create()'s own
    // "call___INIT(ob); ...; apply(APPLY_CREATE, ...)" order, confirmed
    // directly, not just create() alone). create_count reads back as 1,
    // not the corrupted 777 and not the bare-zeroed 0 -- create()
    // genuinely ran again, from the freshly-zeroed baseline, not skipped.
    assert(std::get<int64_t>(harness.vm.callFunction(ob, "get_plain", {}).data) == 0);
    assert(std::get<int64_t>(harness.vm.callFunction(ob, "get_initialized", {}).data) == 5);
    assert(std::get<int64_t>(harness.vm.callFunction(ob, "get_create_count", {}).data) == 1);

    std::cout << "testReloadObjectResetsVariablesReinitializesAndCallsCreateAgain OK\n";
}

static void testReloadObjectClosesOwnedSocketsWithNoCallbackFiring() {
    ObjectVarHarness harness;
    harness.writeFile("/reload_socket.c",
        "int fd;\n"
        "int close_fired;\n"
        "int make() { fd = socket_create(2, \"on_read\", \"on_close\"); return fd; }\n"
        "void on_read(int f, string m, string a) {}\n"
        "void on_close(int f) { close_fired = 1; }\n"
        "int get_close_fired() { return close_fired; }\n");
    auto ob = harness.objects.cloneObject("/reload_socket");
    assert(ob != nullptr);

    amlp::Value madeFd = harness.vm.callFunction(ob, "make", {});
    assert(std::get<int64_t>(madeFd.data) >= 0);
    // Captured *before* reload zeroes ob's own "fd" variable -- reading
    // socket_status() through ob's own (post-reload) fd afterward would
    // check whatever that now-zeroed slot happens to read as instead
    // (0, a handle some *other* still-open socket in this same global
    // registry could easily own), not this test's own actual socket.
    int handle = static_cast<int>(std::get<int64_t>(madeFd.data));

    std::vector<amlp::Value> statusArgsBefore{amlp::Value(int64_t{handle})};
    amlp::Value before = amlp::EfunTable::instance().call("socket_status", harness.vm, statusArgsBefore);
    auto* beforeArr = std::get_if<std::shared_ptr<amlp::Array>>(&before.data);
    assert(beforeArr != nullptr && !(*beforeArr)->items.empty());

    std::vector<amlp::Value> reloadArgs{amlp::Value(ob)};
    amlp::EfunTable::instance().call("reload_object", harness.vm, reloadArgs);

    // Real close_referencing_sockets()'s own "socket_close(i, SC_FORCE)"
    // -- SC_FORCE alone, without SC_DO_CALLBACK, so the socket is gone
    // but on_close() never runs.
    std::vector<amlp::Value> statusArgs{amlp::Value(int64_t{handle})};
    amlp::Value after = amlp::EfunTable::instance().call("socket_status", harness.vm, statusArgs);
    auto* afterArr = std::get_if<std::shared_ptr<amlp::Array>>(&after.data);
    assert(afterArr != nullptr && (*afterArr)->items.empty());
    assert(std::get<int64_t>(harness.vm.callFunction(ob, "get_close_fired", {}).data) == 0);

    std::cout << "testReloadObjectClosesOwnedSocketsWithNoCallbackFiring OK\n";
}

static void testReloadObjectRemovesPendingCallOutsAndDisablesHeartbeat() {
    ObjectVarHarness harness;
    amlp::Scheduler scheduler(harness.vm);
    harness.vm.setScheduler(&scheduler);
    harness.writeFile("/reload_timers.c",
        "int co_fired;\n"
        "int hb_fired;\n"
        "void go() { call_out(\"fire_co\", 0); set_heart_beat(1); }\n"
        "void fire_co() { co_fired = 1; }\n"
        "void heart_beat() { hb_fired = hb_fired + 1; }\n"
        "int get_co_fired() { return co_fired; }\n"
        "int get_hb_fired() { return hb_fired; }\n");
    auto ob = harness.objects.cloneObject("/reload_timers");
    assert(ob != nullptr);

    harness.vm.callFunction(ob, "go", {});

    std::vector<amlp::Value> reloadArgs{amlp::Value(ob)};
    amlp::EfunTable::instance().call("reload_object", harness.vm, reloadArgs);

    // Real "set_heart_beat(obj, 0); remove_all_call_out(obj);" -- neither
    // the pending call_out nor the heartbeat should ever fire once
    // ticked, proving both were genuinely removed, not merely masked.
    scheduler.tickCallOuts();
    scheduler.tickHeartbeats();
    assert(std::get<int64_t>(harness.vm.callFunction(ob, "get_co_fired", {}).data) == 0);
    assert(std::get<int64_t>(harness.vm.callFunction(ob, "get_hb_fired", {}).data) == 0);

    std::cout << "testReloadObjectRemovesPendingCallOutsAndDisablesHeartbeat OK\n";
}

static void testReloadObjectCascadeDestructsObjectsThatWereShadowingIt() {
    ObjectVarHarness harness;
    harness.writeFile("/unused.c",
        "void create() {}\n"
        "int valid_shadow(object ob) { return 1; }\n");
    assert(harness.objects.loadMasterObject());
    harness.writeFile("/reload_sh_victim.c", "void create() {}\n");
    harness.writeFile("/reload_sh_shadow.c",
        "object attach(object victim) { return shadow(victim, 1); }\n");
    auto victim = harness.objects.cloneObject("/reload_sh_victim");
    auto shadowOb = harness.objects.cloneObject("/reload_sh_shadow");
    assert(victim != nullptr && shadowOb != nullptr);

    harness.vm.callFunction(shadowOb, "attach", {amlp::Value(victim)});
    assert(victim->shadowedBy().lock() == shadowOb);

    // victim is the base of the chain (shadowed by shadowOb, shadowing
    // nothing itself) -- real reload_object()'s own cascade destructs
    // every object shadowing it, identical to destruct()'s own real
    // cascade, but victim itself survives (it is being reloaded, not
    // destructed).
    std::vector<amlp::Value> reloadArgs{amlp::Value(victim)};
    amlp::EfunTable::instance().call("reload_object", harness.vm, reloadArgs);

    assert(shadowOb->isDestructed());
    assert(!victim->isDestructed());
    assert(!victim->shadowedBy().lock());

    std::cout << "testReloadObjectCascadeDestructsObjectsThatWereShadowingIt OK\n";
}

static void testReloadObjectSplicesOutWithoutDestructingAnythingWhenItIsItselfTheShadow() {
    ObjectVarHarness harness;
    harness.writeFile("/unused.c",
        "void create() {}\n"
        "int valid_shadow(object ob) { return 1; }\n");
    assert(harness.objects.loadMasterObject());
    harness.writeFile("/reload_sp_victim.c", "void create() {}\n");
    harness.writeFile("/reload_sp_shadow.c",
        "object attach(object victim) { return shadow(victim, 1); }\n");
    auto victim = harness.objects.cloneObject("/reload_sp_victim");
    auto shadowOb = harness.objects.cloneObject("/reload_sp_shadow");
    assert(victim != nullptr && shadowOb != nullptr);

    harness.vm.callFunction(shadowOb, "attach", {amlp::Value(victim)});
    assert(shadowOb->shadowing().lock() == victim);

    // shadowOb is itself the shadow (shadowing victim, shadowed by
    // nothing) -- real reload_object()'s own cascade condition
    // ("obj->shadowed && !obj->shadowing") is false here, so this takes
    // the splice branch instead: shadowOb's own shadowing relationship
    // to victim is severed, and *neither* object gets destructed.
    std::vector<amlp::Value> reloadArgs{amlp::Value(shadowOb)};
    amlp::EfunTable::instance().call("reload_object", harness.vm, reloadArgs);

    assert(!shadowOb->isDestructed());
    assert(!victim->isDestructed());
    assert(!shadowOb->shadowing().lock());
    assert(!victim->shadowedBy().lock());

    std::cout << "testReloadObjectSplicesOutWithoutDestructingAnythingWhenItIsItselfTheShadow OK\n";
}

static void testReloadObjectLeavesAnActiveSnoopRelationshipUntouched() {
    // Real reload_object() (object.c) has no snoop-related line anywhere
    // in its own body -- confirmed directly, unlike destruct_object()'s
    // own explicit snoop unlinking (simulate.c). A snoop relationship
    // involving the reloaded object must survive completely intact.
    ObjectVarHarness harness;
    harness.writeFile("/reload_sn_victim.c", "void create() {}\n");
    harness.writeFile("/reload_sn_snooper.c",
        "object start(object victim) { return snoop(this_object(), victim); }\n");
    auto victim = harness.objects.cloneObject("/reload_sn_victim");
    auto snooper = harness.objects.cloneObject("/reload_sn_snooper");
    assert(victim != nullptr && snooper != nullptr);

    int fds[2];
    assert(::socketpair(AF_UNIX, SOCK_STREAM, 0, fds) == 0);
    amlp::Connection conn(fds[0]);
    conn.attach(victim);

    harness.vm.callFunction(snooper, "start", {amlp::Value(victim)});
    assert(victim->snoopedBy().lock() == snooper);
    assert(snooper->snooping().lock() == victim);

    std::vector<amlp::Value> reloadArgs{amlp::Value(victim)};
    amlp::EfunTable::instance().call("reload_object", harness.vm, reloadArgs);

    assert(victim->snoopedBy().lock() == snooper);
    assert(snooper->snooping().lock() == victim);

    ::close(fds[1]);
    std::cout << "testReloadObjectLeavesAnActiveSnoopRelationshipUntouched OK\n";
}

// destruct(): real destruct_object()'s own "if (ob->flags &
// O_EFUN_SOCKET) close_referencing_sockets(ob);" (simulate.c), the real
// gap found and precisely located while implementing reload_object()'s
// own identical need last session, ported here. Both real semantics
// checked: closing the destructed object's own socket directly, and
// closing a *cascaded* shadow object's own socket too (real
// destruct_object() unconditionally closes referencing sockets for
// whatever it actually destructs, including every object the real
// shadow-chain cascade destructs along with the one named explicitly).

static void testDestructClosesOwnedSocketsWithNoCallbackFiring() {
    ObjectVarHarness harness;
    harness.writeFile("/destruct_socket.c",
        "int close_fired;\n"
        "int make() { return socket_create(2, \"on_read\", \"on_close\"); }\n"
        "void on_read(int f, string m, string a) {}\n"
        "void on_close(int f) { close_fired = 1; }\n"
        "int get_close_fired() { return close_fired; }\n");
    auto ob = harness.objects.cloneObject("/destruct_socket");
    assert(ob != nullptr);

    amlp::Value madeFd = harness.vm.callFunction(ob, "make", {});
    assert(std::get<int64_t>(madeFd.data) >= 0);
    // Captured before destruct(), the same reasoning
    // testReloadObjectClosesOwnedSocketsWithNoCallbackFiring's own
    // comment already establishes -- ob's own variables are not zeroed
    // by destruct() the way reload_object() does, but ob is destructed,
    // and this driver's own callFunction() silently no-ops against a
    // destructed target either way, so reading the handle back through
    // ob afterward would not work regardless.
    int handle = static_cast<int>(std::get<int64_t>(madeFd.data));

    std::vector<amlp::Value> statusArgsBefore{amlp::Value(int64_t{handle})};
    amlp::Value before = amlp::EfunTable::instance().call("socket_status", harness.vm, statusArgsBefore);
    auto* beforeArr = std::get_if<std::shared_ptr<amlp::Array>>(&before.data);
    assert(beforeArr != nullptr && !(*beforeArr)->items.empty());

    std::vector<amlp::Value> destructArgs{amlp::Value(ob)};
    amlp::EfunTable::instance().call("destruct", harness.vm, destructArgs);

    // Real "socket_close(i, SC_FORCE)" -- SC_FORCE alone, without
    // SC_DO_CALLBACK, so the socket is gone but on_close() never runs.
    // ob itself is destructed (not reloaded), so get_close_fired() is
    // read through the still-live local shared_ptr, matching this
    // driver's own established "destructed but still referenced" test
    // pattern rather than through a fresh lookup.
    std::vector<amlp::Value> statusArgsAfter{amlp::Value(int64_t{handle})};
    amlp::Value after = amlp::EfunTable::instance().call("socket_status", harness.vm, statusArgsAfter);
    auto* afterArr = std::get_if<std::shared_ptr<amlp::Array>>(&after.data);
    assert(afterArr != nullptr && (*afterArr)->items.empty());
    assert(ob->isDestructed());

    std::cout << "testDestructClosesOwnedSocketsWithNoCallbackFiring OK\n";
}

static void testDestructShadowCascadeAlsoClosesTheCascadedObjectsOwnSockets() {
    ObjectVarHarness harness;
    harness.writeFile("/unused.c",
        "void create() {}\n"
        "int valid_shadow(object ob) { return 1; }\n");
    assert(harness.objects.loadMasterObject());
    harness.writeFile("/destruct_sh_victim.c", "void create() {}\n");
    harness.writeFile("/destruct_sh_shadow.c",
        "object attach(object victim) { return shadow(victim, 1); }\n"
        "int make() { return socket_create(2, \"on_read\", 0); }\n"
        "void on_read(int f, string m, string a) {}\n");
    auto victim = harness.objects.cloneObject("/destruct_sh_victim");
    auto shadowOb = harness.objects.cloneObject("/destruct_sh_shadow");
    assert(victim != nullptr && shadowOb != nullptr);

    harness.vm.callFunction(shadowOb, "attach", {amlp::Value(victim)});
    assert(victim->shadowedBy().lock() == shadowOb);

    // shadowOb owns a socket of its own -- not victim, the object
    // actually named in the destruct() call below.
    amlp::Value madeFd = harness.vm.callFunction(shadowOb, "make", {});
    assert(std::get<int64_t>(madeFd.data) >= 0);
    int handle = static_cast<int>(std::get<int64_t>(madeFd.data));

    // victim is the base of the chain -- destructing it cascades,
    // destructing shadowOb along with it (the exact same real cascade
    // reload_object()'s own equivalent test already exercises).
    std::vector<amlp::Value> destructArgs{amlp::Value(victim)};
    amlp::EfunTable::instance().call("destruct", harness.vm, destructArgs);
    assert(shadowOb->isDestructed());

    // shadowOb's own socket must be closed too -- proof the callback
    // genuinely threads through the recursive cascade, not just the
    // one object named directly in the destruct() call.
    std::vector<amlp::Value> statusArgs{amlp::Value(int64_t{handle})};
    amlp::Value status = amlp::EfunTable::instance().call("socket_status", harness.vm, statusArgs);
    auto* statusArr = std::get_if<std::shared_ptr<amlp::Array>>(&status.data);
    assert(statusArr != nullptr && (*statusArr)->items.empty());

    std::cout << "testDestructShadowCascadeAlsoClosesTheCascadedObjectsOwnSockets OK\n";
}

// Phase 1 dialect work begins here. LpcDialect/BootApi round trip plus
// the first corrected fact carried over from the 2026-08-22 cross-driver
// comparison session recorded in src/dialect/instruct.md and
// src/apply/instruct.md Phase 1.16: real LDMud's master trust-root UID
// apply is "get_master_uid", not FluffOS's "get_root_uid" -- an earlier
// draft of this project's own docs had attributed the FluffOS name to
// LDMud too. connectApply()/netDeadApply() are deliberately not covered
// here -- see BootApi.hpp's own comment on why those two are still open.

static void testLpcDialectNameAndFromStringRoundTripAllThreeDialects() {
    assert(std::string(amlp::dialectName(amlp::LpcDialect::FluffOS)) == "fluffos");
    assert(std::string(amlp::dialectName(amlp::LpcDialect::LdMud)) == "ldmud");
    assert(std::string(amlp::dialectName(amlp::LpcDialect::DGD)) == "dgd");

    assert(amlp::dialectFromString("fluffos") == amlp::LpcDialect::FluffOS);
    assert(amlp::dialectFromString("ldmud") == amlp::LpcDialect::LdMud);
    assert(amlp::dialectFromString("dgd") == amlp::LpcDialect::DGD);

    bool threw = false;
    try {
        amlp::dialectFromString("not_a_real_dialect");
    } catch (const std::invalid_argument&) {
        threw = true;
    }
    assert(threw);

    std::cout << "testLpcDialectNameAndFromStringRoundTripAllThreeDialects OK\n";
}

// ROADMAP.md rows 1.2/1.3, greenlit first slice: dialect plumbing through
// Lexer/Parser constructors (default LpcDialect::FluffOS, zero behavior
// change for any pre-existing call site -- exercised implicitly by every
// other test in this file still constructing Lexer/Parser with no dialect
// argument at all) plus DGD's real "atomic" function-declaration modifier
// as the first real per-dialect token (confirmed against
// temp/dgd/src/comp/parser.y's own "ATOMIC { $$ = C_ATOMIC; }", the same
// modifier-list production as static/nomask/varargs).
static void testLexerAtomicKeywordOnlyRecognizedUnderDgdDialect() {
    // Default-constructed Lexer (no dialect argument) must behave exactly
    // like explicit FluffOS -- the "byte-identical to before this change"
    // requirement, checked directly rather than just assumed.
    {
        amlp::Lexer lexer("atomic");
        auto tokens = lexer.tokenize();
        assert(tokens.size() == 2); // "atomic", End
        assert(tokens[0].type == amlp::TokenType::Ident);
        assert(tokens[0].text == "atomic");
    }
    {
        amlp::Lexer lexer("atomic", amlp::LpcDialect::FluffOS);
        auto tokens = lexer.tokenize();
        assert(tokens[0].type == amlp::TokenType::Ident);
    }
    {
        amlp::Lexer lexer("atomic", amlp::LpcDialect::LdMud);
        auto tokens = lexer.tokenize();
        assert(tokens[0].type == amlp::TokenType::Ident);
    }
    {
        amlp::Lexer lexer("atomic", amlp::LpcDialect::DGD);
        auto tokens = lexer.tokenize();
        assert(tokens[0].type == amlp::TokenType::Keyword);
        assert(tokens[0].text == "atomic");
    }

    std::cout << "testLexerAtomicKeywordOnlyRecognizedUnderDgdDialect OK\n";
}

static void testCompileAtomicFunctionModifierAcceptedOnlyUnderDgdDialect() {
    // A function declaration using "atomic" as a leading modifier, real
    // DGD shape (temp/dgd/src/comp/parser.y's own non_private production).
    // Under FluffOS/LDMud, "atomic" lexes as a plain Ident (confirmed
    // above), so parseDeclPrefix()'s modifier loop never consumes it;
    // falling through to the "type omitted" branch instead misreads
    // "atomic" itself as the declaration's own name, then chokes on the
    // real return-type keyword "void" immediately after -- a genuine
    // parse error, not a silent misparse, caught by
    // ObjectManager::compile()'s own try/catch and surfaced as a null
    // program exactly like any other real compile failure.
    const char* src = "atomic void go() { return; }\n";

    {
        ObjectVarHarness harness; // defaults to "fluffos", row 1.1
        harness.writeFile("/atomic_fluffos.c", src);
        auto ob = harness.objects.cloneObject("/atomic_fluffos");
        assert(ob == nullptr);
    }
    {
        ObjectVarHarness harness("dialect: ldmud\n");
        harness.writeFile("/atomic_ldmud.c", src);
        auto ob = harness.objects.cloneObject("/atomic_ldmud");
        assert(ob == nullptr);
    }
    {
        ObjectVarHarness harness("dialect: dgd\n");
        harness.writeFile("/atomic_dgd.c", src);
        auto ob = harness.objects.cloneObject("/atomic_dgd");
        assert(ob != nullptr);
        // Confirms this is a genuine, working function, not just a
        // program object that happened not to be null: "atomic" was
        // consumed purely as a modifier, "go" is the real function name,
        // callable and returning normally.
        harness.vm.callFunction(ob, "go", {});
    }

    std::cout << "testCompileAtomicFunctionModifierAcceptedOnlyUnderDgdDialect OK\n";
}

// ROADMAP.md row 1.2/1.3's own next greenlit slice, same gated-per-dialect
// pattern as "atomic" just above: DGD's real "nil" literal (confirmed
// against temp/dgd/src/comp/parser.y's own "NIL { $$ = Node::createNil();
// }", temp/dgd/src/data.h's own "T_NIL"/VAL_TRUE/VAL_NIL macros, and
// temp/dgd/src/data.cpp's own "nil.type = (stricttc) ? T_NIL : T_INT;" --
// this implementation targets strict-typechecking DGD's own behavior,
// the only mode where nil is a real distinct value rather than plain
// int 0).
static void testLexerNilKeywordOnlyRecognizedUnderDgdDialect() {
    {
        amlp::Lexer lexer("nil");
        auto tokens = lexer.tokenize();
        assert(tokens[0].type == amlp::TokenType::Ident); // default == FluffOS
    }
    {
        amlp::Lexer lexer("nil", amlp::LpcDialect::FluffOS);
        auto tokens = lexer.tokenize();
        assert(tokens[0].type == amlp::TokenType::Ident);
    }
    {
        amlp::Lexer lexer("nil", amlp::LpcDialect::LdMud);
        auto tokens = lexer.tokenize();
        assert(tokens[0].type == amlp::TokenType::Ident);
    }
    {
        amlp::Lexer lexer("nil", amlp::LpcDialect::DGD);
        auto tokens = lexer.tokenize();
        assert(tokens[0].type == amlp::TokenType::Keyword);
        assert(tokens[0].text == "nil");
    }

    std::cout << "testLexerNilKeywordOnlyRecognizedUnderDgdDialect OK\n";
}

static void testCompileNilLiteralAcceptedOnlyUnderDgdDialectAndEvaluatesCorrectly() {
    // Under FluffOS/LDMud, "nil" lexes as a plain Ident (confirmed
    // above), so parsePrimary() never reaches the dialect-gated literal
    // branch; "return nil;" parses as an ordinary bare-identifier
    // VarRefExpr instead (syntactically valid -- unlike "atomic", this
    // is not a parse error), which then fails at CodeGen time instead:
    // CodeGen::resolveVariable() throws "codegen: undeclared variable
    // \"nil\"" since no local or object variable named "nil" exists --
    // still a genuine compile failure, caught by the same
    // ObjectManager::compile() try/catch, just from a different stage
    // than atomic's parse-time failure. Exactly the "gets misread as an
    // identifier" alternative this slice's own task description called
    // out as equally real and acceptable.
    const char* src =
        "mixed getNil() { return nil; }\n"
        "mixed nilIsFalsy() { return nil ? 1 : 0; }\n"
        "mixed nilEqualsNil() { return nil == nil; }\n"
        "mixed nilEqualsZero() { return nil == 0; }\n";

    {
        ObjectVarHarness harness; // defaults to "fluffos", row 1.1
        harness.writeFile("/nil_fluffos.c", src);
        auto ob = harness.objects.cloneObject("/nil_fluffos");
        assert(ob == nullptr);
    }
    {
        ObjectVarHarness harness("dialect: ldmud\n");
        harness.writeFile("/nil_ldmud.c", src);
        auto ob = harness.objects.cloneObject("/nil_ldmud");
        assert(ob == nullptr);
    }
    {
        ObjectVarHarness harness("dialect: dgd\n");
        harness.writeFile("/nil_dgd.c", src);
        auto ob = harness.objects.cloneObject("/nil_dgd");
        assert(ob != nullptr);

        // A real nil literal compiles and evaluates: PushNil pushes a
        // genuine amlp::Nil-holding Value, not int64_t 0 or monostate.
        amlp::Value got = harness.vm.callFunction(ob, "getNil", {});
        assert(std::holds_alternative<amlp::Nil>(got.data));

        // isTruthy(nil) == false, real VAL_TRUE(v) semantics.
        amlp::Value truthy = harness.vm.callFunction(ob, "nilIsFalsy", {});
        assert(std::holds_alternative<int64_t>(truthy.data));
        assert(std::get<int64_t>(truthy.data) == 0);

        // nil == nil is true (real VAL_NIL(v), always true for a value
        // already known to be nil-typed).
        amlp::Value eqNil = harness.vm.callFunction(ob, "nilEqualsNil", {});
        assert(std::holds_alternative<int64_t>(eqNil.data));
        assert(std::get<int64_t>(eqNil.data) == 1);

        // nil == 0 is false -- real strict-typechecking DGD's own
        // distinct T_NIL vs T_INT type tags, not the same value.
        amlp::Value eqZero = harness.vm.callFunction(ob, "nilEqualsZero", {});
        assert(std::holds_alternative<int64_t>(eqZero.data));
        assert(std::get<int64_t>(eqZero.data) == 0);
    }

    std::cout << "testCompileNilLiteralAcceptedOnlyUnderDgdDialectAndEvaluatesCorrectly OK\n";
}

// ROADMAP.md row 1.2/1.3's own next real Phase 1 slice after the DGD work
// above: LDMud's own "#'name" closure-literal prefix, bare-name form only
// (confirmed against temp/ldmud/src/lex.c's own closure() function --
// see Lexer::lexHashQuote()'s own comment for the full citation and what
// is deliberately not covered yet). Same double-gated-per-dialect
// discipline as "atomic"/"nil" above, but unlike either of those, "#" is
// not lexable under FluffOS/DGD at all today (not merely misread as a
// plain Ident the way "atomic"/"nil" are) -- so the "other dialects"
// half of these tests confirms a genuine Lexer exception, not just a
// different token type.
static void testLexerHashQuoteClosureOnlyRecognizedUnderLdmudDialect() {
    {
        amlp::Lexer lexer("#'foo"); // default == FluffOS
        bool threw = false;
        try {
            lexer.tokenize();
        } catch (const amlp::LpcRuntimeError&) {
            threw = true;
        }
        assert(threw);
    }
    {
        amlp::Lexer lexer("#'foo", amlp::LpcDialect::FluffOS);
        bool threw = false;
        try {
            lexer.tokenize();
        } catch (const amlp::LpcRuntimeError&) {
            threw = true;
        }
        assert(threw);
    }
    {
        amlp::Lexer lexer("#'foo", amlp::LpcDialect::DGD);
        bool threw = false;
        try {
            lexer.tokenize();
        } catch (const amlp::LpcRuntimeError&) {
            threw = true;
        }
        assert(threw);
    }
    {
        amlp::Lexer lexer("#'foo", amlp::LpcDialect::LdMud);
        auto tokens = lexer.tokenize();
        assert(tokens.size() == 3); // "#'", "foo", End
        assert(tokens[0].type == amlp::TokenType::Symbol);
        assert(tokens[0].text == "#'");
        assert(tokens[1].type == amlp::TokenType::Ident);
        assert(tokens[1].text == "foo");
        assert(tokens[2].type == amlp::TokenType::End);
    }

    std::cout << "testLexerHashQuoteClosureOnlyRecognizedUnderLdmudDialect OK\n";
}

static void testCompileHashQuoteClosureAcceptedOnlyUnderLdmudDialectAndEvaluatesCorrectly() {
    // Deliberately routed through ObjectVarHarness, not compileProgramObject
    // (which bypasses ObjectManager::compile() and its real cpp
    // preprocessing step entirely) -- this needs the genuine end-to-end
    // path to actually exercise the cpp-masking architecture fix
    // (ObjectManager.cpp's maskHashQuote()/unmaskHashQuote()), not just
    // the Lexer/Parser in isolation. The bare "#'lower_case;" statement on
    // its own line below is the exact failure shape ROADMAP.md's own
    // scoping note cited ("a bare #'this_player; statement written on its
    // own line... would make the whole file fail preprocessing") -- if
    // the masking fix regressed, this file would fail to compile under
    // *any* dialect, including fluffos/dgd, not just misparse under them.
    const char* src =
        "string probe() {\n"
        "    mixed f;\n"
        "    #'lower_case;\n"
        "    f = #'lower_case;\n"
        "    return funcall(f, \"ABC\");\n"
        "}\n";

    {
        ObjectVarHarness harness; // defaults to "fluffos", row 1.1
        harness.writeFile("/hashquote_fluffos.c", src);
        auto ob = harness.objects.cloneObject("/hashquote_fluffos");
        assert(ob == nullptr);
    }
    {
        ObjectVarHarness harness("dialect: dgd\n");
        harness.writeFile("/hashquote_dgd.c", src);
        auto ob = harness.objects.cloneObject("/hashquote_dgd");
        assert(ob == nullptr);
    }
    {
        ObjectVarHarness harness("dialect: ldmud\n");
        harness.writeFile("/hashquote_ldmud.c", src);
        auto ob = harness.objects.cloneObject("/hashquote_ldmud");
        assert(ob != nullptr);

        // Real closure semantics, not just "it parsed": "#'lower_case" is
        // stored in f with no bound args, and funcall() supplies "ABC" at
        // call time -- the exact same PushClosure/evaluate machinery
        // "(: lower_case :)" already uses (see
        // testFuncallIsAnAliasOfEvaluate just above), reached here through
        // LDMud's own spelling of the identical concept instead.
        amlp::Value result = harness.vm.callFunction(ob, "probe", {});
        assert(std::holds_alternative<std::string>(result.data));
        assert(std::get<std::string>(result.data) == "abc");
    }

    std::cout << "testCompileHashQuoteClosureAcceptedOnlyUnderLdmudDialectAndEvaluatesCorrectly OK\n";
}

// ROADMAP.md row 1.2/1.3's own next real corpus-frequency-ranked slice
// after bare "#'name": LDMud's own "#'efun::name" scope-prefixed closure
// literal (temp/ldmud/doc/LPC/closures's own real citation: "closure to
// an efun"), picked over the other three deliberately-uncovered forms
// (operator spellings, #'[ index forms, #'({ aggregates) because it was
// the *only* one with any confirmed real occurrence anywhere across this
// repo's full vendored corpus search -- see this session's own STATUS.md
// entry for the full ranking. See Parser.cpp's own comment at the
// "#'efun::" recognition site for the full citation and scoping
// (sefun::/lfun:: tier-forcing and var:: -- a genuinely different closure
// kind, not just a resolution-tier hint -- deliberately still not
// covered).
static void testHashQuoteEfunPrefixParsesToClosureLiteralExprWithForceEfun() {
    amlp::Lexer lexer("mixed probe() { return #'efun::lower_case; }", amlp::LpcDialect::LdMud);
    amlp::Parser parser(lexer.tokenize(), amlp::LpcDialect::LdMud);
    auto program = parser.parseProgram();

    auto& body = program->functions[0]->body->statements;
    auto* ret = dynamic_cast<amlp::ReturnStmt*>(body[0].get());
    assert(ret != nullptr);
    auto* closure = dynamic_cast<amlp::ClosureLiteralExpr*>(ret->expr.get());
    assert(closure != nullptr);
    assert(closure->functionName == "lower_case");
    assert(closure->forceEfun == true);
    assert(closure->boundArgs.empty());

    std::cout << "testHashQuoteEfunPrefixParsesToClosureLiteralExprWithForceEfun OK\n";
}

static void testHashQuoteEfunPrefixBypassesALocalFunctionOfTheSameNameUnlikeBareForm() {
    // The real semantic "#'efun::" is actually for, not just a spelling
    // difference: real LDMud's own tiered closure resolution would
    // otherwise let a local lfun of the same name win, exactly like a
    // bare call would -- "#'efun::name" is the explicit escape hatch past
    // that, guaranteed to reach the core efun regardless of what this
    // object itself defines. Confirmed here by literally shadowing a real
    // efun (lower_case) with a local function of the same name that
    // returns an observably different, distinguishable value, then
    // showing the two closure forms resolve to two different targets.
    const char* src =
        "string lower_case(string s) { return \"SHADOWED:\" + s; }\n"
        "string probeBare() { return funcall(#'lower_case, \"ABC\"); }\n"
        "string probeEfun() { return funcall(#'efun::lower_case, \"ABC\"); }\n";

    ObjectVarHarness harness("dialect: ldmud\n");
    harness.writeFile("/hashquote_efun_shadow.c", src);
    auto ob = harness.objects.cloneObject("/hashquote_efun_shadow");
    assert(ob != nullptr);

    // Bare "#'lower_case" resolves through the normal tiered lookup --
    // this object's own local lower_case() wins, exactly like an ordinary
    // bare call to lower_case(...) from inside this same object would.
    amlp::Value bareResult = harness.vm.callFunction(ob, "probeBare", {});
    assert(std::holds_alternative<std::string>(bareResult.data));
    assert(std::get<std::string>(bareResult.data) == "SHADOWED:ABC");

    // "#'efun::lower_case" bypasses that local override entirely and
    // reaches the real core efun -- real lower_case("ABC") == "abc", not
    // the local function's own "SHADOWED:ABC".
    amlp::Value efunResult = harness.vm.callFunction(ob, "probeEfun", {});
    assert(std::holds_alternative<std::string>(efunResult.data));
    assert(std::get<std::string>(efunResult.data) == "abc");

    std::cout << "testHashQuoteEfunPrefixBypassesALocalFunctionOfTheSameNameUnlikeBareForm OK\n";
}

// ROADMAP.md row 1.7/1.8's own unbound_lambda() investigation: real
// LDMud's own "'name" symbol literal (see Value.hpp's Symbol and
// Lexer::lexQuote() for the real-source citation). Confirms the
// disambiguation from an ordinary character constant, and that "'name"
// stays a plain (unimplemented-as-a-symbol, still just a char literal)
// lexing outside LpcDialect::LdMud -- neither FluffOS nor DGD has a
// symbol-literal concept at all.
static void testSymbolLiteralLexesDistinctFromCharLiteralUnderLdmudDialectOnly() {
    {
        amlp::Lexer lexer("'item", amlp::LpcDialect::LdMud);
        auto tokens = lexer.tokenize();
        assert(tokens.size() == 2); // symbol, End
        assert(tokens[0].type == amlp::TokenType::QuotedSymbol);
        assert(tokens[0].text == "item");
    }
    {
        // Ordinary single-character constant stays a char literal (Number
        // token, real LPC's own int-encoding-of-a-char), not a symbol --
        // real lex.c's own "'x'" case, see Lexer::lexQuote()'s comment.
        amlp::Lexer lexer("'a'", amlp::LpcDialect::LdMud);
        auto tokens = lexer.tokenize();
        assert(tokens.size() == 2); // number, End
        assert(tokens[0].type == amlp::TokenType::Number);
        assert(tokens[0].text == "97"); // 'a' == 97
    }
    {
        // Under FluffOS, "'item" is not a symbol at all -- lexChar()'s
        // pre-existing behavior (a char literal must contain exactly one
        // character) is completely unchanged, so this throws exactly as
        // it always did.
        amlp::Lexer lexer("'item", amlp::LpcDialect::FluffOS);
        bool threw = false;
        try {
            lexer.tokenize();
        } catch (const amlp::LpcRuntimeError&) {
            threw = true;
        }
        assert(threw);
    }

    std::cout << "testSymbolLiteralLexesDistinctFromCharLiteralUnderLdmudDialectOnly OK\n";
}

// ROADMAP.md row 1.7/1.8's own bounded first sub-slice, picked via a
// fresh corpus re-check that session (see this session's own STATUS.md
// entry): real secure/master/hooks.c has exactly 4 real unbound_lambda()
// call sites (lambda(), bind_lambda() alone: 0 real hits anywhere in
// temp/'s vendored corpora), all handed straight to set_driver_hook()
// (itself still unimplemented -- this test cannot exercise that half at
// all, and does not try to). What this test does confirm end to end,
// mirroring hooks.c's own H_MOVE_OBJECT0 hook body shape
// ("unbound_lambda( ({'item, 'dest}), ({#'moveHook, 'item, 'dest }) )")
// as closely as this driver's own eval surface allows: the closure is
// genuinely uncallable until bound (real interpret.c's own "Uncallable
// closure", int_call_lambda()), and once bound (via bind_lambda(), the
// same real LDMud efun -- real driver-hook dispatch itself auto-binds
// internally at call time instead, see VM.cpp's own callClosure()
// comment) it runs the real quoted-code call tree correctly, positional
// symbol substitution and all.
static void testUnboundLambdaIsUncallableUntilBoundThenRunsHooksCsOwnQuotedCodeShape() {
    ObjectVarHarness harness("dialect: ldmud\n");
    harness.writeFile("/unbound_move.c",
        "mixed lastItem; mixed lastDest;\n"
        "mixed moveHook(mixed item, mixed dest) {\n"
        "    lastItem = item; lastDest = dest;\n"
        "    return item + dest;\n"
        "}\n"
        "mixed makeHook() {\n"
        "    return unbound_lambda( ({'item, 'dest}),\n"
        "        ({#'moveHook, 'item, 'dest }) );\n"
        "}\n"
        "mixed callDirect(mixed c) { return funcall(c, 3, 4); }\n"
        "mixed bindIt(mixed c) { return bind_lambda(c); }\n"
        "mixed getLastItem() { return lastItem; }\n"
        "mixed getLastDest() { return lastDest; }\n");
    auto ob = harness.objects.cloneObject("/unbound_move");
    assert(ob != nullptr);

    amlp::Value hookVal = harness.vm.callFunction(ob, "makeHook", {});
    auto hookClosure = std::get<std::shared_ptr<amlp::Closure>>(hookVal.data);
    assert(hookClosure != nullptr);
    assert(hookClosure->unboundUntilBound);

    // Real "Uncallable closure" -- calling it before bind_lambda() must
    // fail exactly the way real int_call_lambda() does with no bind_ob.
    bool threw = false;
    try {
        harness.vm.callFunction(ob, "callDirect", {hookVal});
    } catch (const amlp::LpcRuntimeError& e) {
        threw = true;
        // run()'s own object/function-name error-context prefix (same
        // convention every other in-VM LpcRuntimeError already gets),
        // hence find() rather than an exact match -- the real message
        // text itself is still the exact real "Uncallable closure".
        assert(std::string(e.what()).find("Uncallable closure") != std::string::npos);
    }
    assert(threw);

    amlp::Value boundVal = harness.vm.callFunction(ob, "bindIt", {hookVal});
    auto boundClosure = std::get<std::shared_ptr<amlp::Closure>>(boundVal.data);
    assert(boundClosure != nullptr);
    assert(!boundClosure->unboundUntilBound);

    amlp::Value result = harness.vm.callFunction(ob, "callDirect", {boundVal});
    assert(std::holds_alternative<int64_t>(result.data));
    assert(std::get<int64_t>(result.data) == 7); // moveHook(3, 4) -> 3 + 4

    amlp::Value item = harness.vm.callFunction(ob, "getLastItem", {});
    amlp::Value dest = harness.vm.callFunction(ob, "getLastDest", {});
    assert(std::get<int64_t>(item.data) == 3);
    assert(std::get<int64_t>(dest.data) == 4);

    std::cout << "testUnboundLambdaIsUncallableUntilBoundThenRunsHooksCsOwnQuotedCodeShape OK\n";
}

// The H_LOAD_UIDS hook body shape (real hooks.c: "unbound_lambda(
// ({'object_name}), ({ #'loadUIDs, 'object_name, ({#'previous_object})
// }) )") is a *nested* quoted call -- one call tree inside another, the
// inner one taking no lambda-parameter arguments at all, only a plain
// already-implemented efun closure. Confirms VM::evalQuotedLambdaNode()'s
// own recursion handles that correctly, not just the single flat call
// H_MOVE_OBJECT0's own shape already covers above.
static void testUnboundLambdaNestedQuotedCallMatchesHooksCsLoadUidsShape() {
    ObjectVarHarness harness("dialect: ldmud\n");
    harness.writeFile("/unbound_nested.c",
        "mixed loadUIDs(mixed objectName, mixed prev) { return ({ objectName, prev }); }\n"
        "mixed makeHook() {\n"
        "    return unbound_lambda( ({'object_name}), ({\n"
        "        #'loadUIDs, 'object_name, ({#'previous_object}) }) );\n"
        "}\n"
        "mixed run(mixed c) { return funcall(bind_lambda(c), \"/std/thing\"); }\n");
    auto ob = harness.objects.cloneObject("/unbound_nested");
    assert(ob != nullptr);

    amlp::Value hookVal = harness.vm.callFunction(ob, "makeHook", {});
    amlp::Value result = harness.vm.callFunction(ob, "run", {hookVal});
    auto arr = std::get<std::shared_ptr<amlp::Array>>(result.data);
    assert(arr->items.size() == 2);
    assert(std::get<std::string>(arr->items[0].data) == "/std/thing");
    // previous_object() with no call_other() in progress: this driver's
    // own existing previous_object() returns void here (not new to this
    // slice, see its own EfunTable.cpp registration) -- the point of
    // this assertion is confirming the *nested* quoted call ran at all
    // (arr has both elements, not that it threw partway through), not
    // previous_object()'s own already-tested return-value convention.
    assert(arr->items[1].isVoid());

    std::cout << "testUnboundLambdaNestedQuotedCallMatchesHooksCsLoadUidsShape OK\n";
}

// A symbol inside the quoted body that is not one of the lambda's own
// declared parameters honestly errors (real LDMud also lets a symbol
// reference the bound object's own global variables, a distinct real
// form this driver does not implement -- see VM::evalQuotedLambdaNode()'s
// own comment) rather than silently returning void/0 for a name the
// caller very likely meant to bind correctly.
