// parse_sentence()'s own third argument (real `parse_env`): an explicit
// object-array override for loadObjects()'s candidate universe, real as
// of this session (housekeeping item 1 -- confirmed already fully
// implemented on the loadObjects() side, this was purely a wiring gap).
// A lamp sitting in a DIFFERENT room than the player, unreachable via
// the ordinary environment walk, resolves anyway when explicitly passed
// via `env` -- and does NOT resolve without it, proving the override
// genuinely substitutes the search space rather than merely adding to
// it.
static void testParseSentenceExplicitEnvArrayOverridesTheOrdinaryEnvironmentWalk() {
    ObjectVarHarness harness;
    harness.writeFile("/pe_roomA.c",
        "void setup() { parse_init(); }\n"
        "mixed *parse_command_id_list() { return ({\"rooma\"}); }\n"
        "int is_living() { return 0; }\n"
        "int inventory_accessible() { return 1; }\n"
        "int inventory_visible() { return 1; }\n");
    harness.writeFile("/pe_roomB.c",
        "void setup() { parse_init(); }\n"
        "mixed *parse_command_id_list() { return ({\"roomb\"}); }\n"
        "int is_living() { return 0; }\n"
        "int inventory_accessible() { return 1; }\n"
        "int inventory_visible() { return 1; }\n");
    harness.writeFile("/pe_lamp.c",
        "void setup() { parse_init(); }\n"
        "void go(object dest) { move_object(dest); }\n"
        "mixed *parse_command_id_list() { return ({\"lamp\"}); }\n"
        "int is_living() { return 0; }\n"
        "int inventory_accessible() { return 1; }\n"
        "int inventory_visible() { return 1; }\n");
    harness.writeFile("/pe_player.c",
        "void setup() { parse_init(); parse_add_rule(\"get\", \"OBJ\"); }\n"
        "void go(object dest) { move_object(dest); }\n"
        "mixed *parse_command_id_list() { return ({\"adventurer\"}); }\n"
        "int is_living() { return 1; }\n"
        "int inventory_accessible() { return 1; }\n"
        "int inventory_visible() { return 1; }\n"
        "int can_get_obj(mixed a) { return 1; }\n"
        "int direct_get_obj(object a) { return 1; }\n"
        "object gotIt;\n"
        "void do_get_obj(object a) { gotIt = a; }\n"
        "mixed runPlain(string s) { return parse_sentence(s); }\n"
        "mixed runWithEnv(string s, object *env) { return parse_sentence(s, 0, env); }\n"
        "object probe() { return gotIt; }\n");

    auto roomA = harness.objects.cloneObject("/pe_roomA");
    auto roomB = harness.objects.cloneObject("/pe_roomB");
    auto player = harness.objects.cloneObject("/pe_player");
    auto lamp = harness.objects.cloneObject("/pe_lamp");
    assert(roomA && roomB && player && lamp);
    for (auto& ob : {roomA, roomB, player, lamp}) harness.vm.callFunction(ob, "setup", {});
    harness.vm.callFunction(player, "go", std::vector<amlp::Value>{amlp::Value(roomA)});
    harness.vm.callFunction(lamp, "go", std::vector<amlp::Value>{amlp::Value(roomB)}); // NOT roomA

    // Without an env override: the lamp is unreachable from the
    // player's own actual room, so the match genuinely fails.
    amlp::Value plainResult =
        harness.vm.callFunction(player, "runPlain", std::vector<amlp::Value>{amlp::Value(std::string("get lamp"))});
    assert(std::holds_alternative<int64_t>(plainResult.data));
    assert(std::get<int64_t>(plainResult.data) != 1);

    // With an explicit env array naming the lamp directly: the match
    // succeeds, resolving to the real lamp object, even though it is
    // still physically sitting in roomB.
    auto envArr = std::make_shared<amlp::Array>();
    envArr->items.push_back(amlp::Value(lamp));
    amlp::Value envResult = harness.vm.callFunction(
        player, "runWithEnv", std::vector<amlp::Value>{amlp::Value(std::string("get lamp")), amlp::Value(envArr)});
    assert(std::holds_alternative<int64_t>(envResult.data));
    assert(std::get<int64_t>(envResult.data) == 1);
    assert(std::get<std::shared_ptr<amlp::LpcObject>>(harness.vm.callFunction(player, "probe", {}).data) == lamp);

    std::cout << "testParseSentenceExplicitEnvArrayOverridesTheOrdinaryEnvironmentWalk OK\n";
}

// ROADMAP.md row 0.13a's own "nicks" note, implemented 2026-08-20: real
// add_nicknames()/expand_node() (packages/parser.c:1095-1108/1302-1323).
// A nickname word ("sam") that is not any real noun id of the target
// object at all -- only the 4th-argument nicks mapping ties the two
// together -- correctly resolves to that object when the object is part
// of this same call's own loadObjects() universe (here: same room as
// the player, the ordinary reachability rule every other noun already
// follows).
static void testParseSentenceNicknameResolvesToAnAlreadyLoadedObject() {
    ObjectVarHarness harness;
    harness.writeFile("/nk_room.c",
        "void setup() { parse_init(); }\n"
        "mixed *parse_command_id_list() { return ({\"room\"}); }\n"
        "int is_living() { return 0; }\n"
        "int inventory_accessible() { return 1; }\n"
        "int inventory_visible() { return 1; }\n");
    harness.writeFile("/nk_widget.c",
        "void setup() { parse_init(); }\n"
        "void go(object dest) { move_object(dest); }\n"
        // deliberately NOT named "sam" -- the only way "get sam" can
        // resolve to this object at all is through the nicks mapping.
        "mixed *parse_command_id_list() { return ({\"widget\"}); }\n"
        "int is_living() { return 0; }\n"
        "int inventory_accessible() { return 1; }\n"
        "int inventory_visible() { return 1; }\n");
    harness.writeFile("/nk_player.c",
        "void setup() { parse_init(); parse_add_rule(\"get\", \"OBJ\"); }\n"
        "void go(object dest) { move_object(dest); }\n"
        "mixed *parse_command_id_list() { return ({\"adventurer\"}); }\n"
        "int is_living() { return 1; }\n"
        "int inventory_accessible() { return 1; }\n"
        "int inventory_visible() { return 1; }\n"
        "int can_get_obj(mixed a) { return 1; }\n"
        "int direct_get_obj(object a) { return 1; }\n"
        "object gotIt;\n"
        "void do_get_obj(object a) { gotIt = a; }\n"
        "mixed runWithNicks(string s, mapping n) { return parse_sentence(s, 0, 0, n); }\n"
        "object probe() { return gotIt; }\n");

    auto room = harness.objects.cloneObject("/nk_room");
    auto player = harness.objects.cloneObject("/nk_player");
    auto widget = harness.objects.cloneObject("/nk_widget");
    assert(room && player && widget);
    for (auto& ob : {room, player, widget}) harness.vm.callFunction(ob, "setup", {});
    harness.vm.callFunction(player, "go", std::vector<amlp::Value>{amlp::Value(room)});
    harness.vm.callFunction(widget, "go", std::vector<amlp::Value>{amlp::Value(room)}); // same room as the player

    auto nicks = std::make_shared<amlp::Mapping>();
    nicks->entries.emplace_back(amlp::Value(std::string("sam")), amlp::Value(widget));
    amlp::Value result = harness.vm.callFunction(
        player, "runWithNicks",
        std::vector<amlp::Value>{amlp::Value(std::string("get sam")), amlp::Value(nicks)});
    assert(std::holds_alternative<int64_t>(result.data));
    assert(std::get<int64_t>(result.data) == 1);
    assert(std::get<std::shared_ptr<amlp::LpcObject>>(harness.vm.callFunction(player, "probe", {}).data) == widget);

    std::cout << "testParseSentenceNicknameResolvesToAnAlreadyLoadedObject OK\n";
}

// The other real half of expand_node()'s own lazy-lookup rule: the
// nickname key is present in the mapping and genuinely maps to a real,
// live, non-destructed object -- but that object was never reached by
// this call's own loadObjects() walk (here: it is sitting in a
// different, unrelated room, exactly like the env-array test's own
// lamp-in-roomB setup above, just reached via a nickname instead of an
// explicit env override). Real expand_node()'s own final linear scan
// over loaded_objects[] never finds it, so the word correctly does not
// resolve as a noun at all -- not an error, a silent, correct
// non-match, the same outcome any other out-of-reach candidate gets.
static void testParseSentenceNicknamePresentButObjectNotYetLoadedDoesNotResolve() {
    ObjectVarHarness harness;
    harness.writeFile("/nk2_roomA.c",
        "void setup() { parse_init(); }\n"
        "mixed *parse_command_id_list() { return ({\"rooma\"}); }\n"
        "int is_living() { return 0; }\n"
        "int inventory_accessible() { return 1; }\n"
        "int inventory_visible() { return 1; }\n");
    harness.writeFile("/nk2_roomB.c",
        "void setup() { parse_init(); }\n"
        "mixed *parse_command_id_list() { return ({\"roomb\"}); }\n"
        "int is_living() { return 0; }\n"
        "int inventory_accessible() { return 1; }\n"
        "int inventory_visible() { return 1; }\n");
    harness.writeFile("/nk2_widget.c",
        "void setup() { parse_init(); }\n"
        "void go(object dest) { move_object(dest); }\n"
        "mixed *parse_command_id_list() { return ({\"widget\"}); }\n"
        "int is_living() { return 0; }\n"
        "int inventory_accessible() { return 1; }\n"
        "int inventory_visible() { return 1; }\n");
    harness.writeFile("/nk2_player.c",
        "void setup() { parse_init(); parse_add_rule(\"get\", \"OBJ\"); }\n"
        "void go(object dest) { move_object(dest); }\n"
        "mixed *parse_command_id_list() { return ({\"adventurer\"}); }\n"
        "int is_living() { return 1; }\n"
        "int inventory_accessible() { return 1; }\n"
        "int inventory_visible() { return 1; }\n"
        "int can_get_obj(mixed a) { return 1; }\n"
        "int direct_get_obj(object a) { return 1; }\n"
        "object gotIt;\n"
        "void do_get_obj(object a) { gotIt = a; }\n"
        "mixed runWithNicks(string s, mapping n) { return parse_sentence(s, 0, 0, n); }\n"
        "object probe() { return gotIt; }\n");

    auto roomA = harness.objects.cloneObject("/nk2_roomA");
    auto roomB = harness.objects.cloneObject("/nk2_roomB");
    auto player = harness.objects.cloneObject("/nk2_player");
    auto widget = harness.objects.cloneObject("/nk2_widget");
    assert(roomA && roomB && player && widget);
    for (auto& ob : {roomA, roomB, player, widget}) harness.vm.callFunction(ob, "setup", {});
    harness.vm.callFunction(player, "go", std::vector<amlp::Value>{amlp::Value(roomA)});
    harness.vm.callFunction(widget, "go", std::vector<amlp::Value>{amlp::Value(roomB)}); // NOT roomA -- unreachable

    auto nicks = std::make_shared<amlp::Mapping>();
    nicks->entries.emplace_back(amlp::Value(std::string("sam")), amlp::Value(widget));
    amlp::Value result = harness.vm.callFunction(
        player, "runWithNicks",
        std::vector<amlp::Value>{amlp::Value(std::string("get sam")), amlp::Value(nicks)});
    assert(std::holds_alternative<int64_t>(result.data));
    assert(std::get<int64_t>(result.data) != 1); // correctly does not resolve
    // do_get_obj() never ran, so gotIt stays its default-initialized real
    // 0 (LpcObject::LpcObject()'s own comment on why an unset object
    // variable reads back as int64_t 0, not a null object reference).
    assert(std::get<int64_t>(harness.vm.callFunction(player, "probe", {}).data) == 0);

    std::cout << "testParseSentenceNicknamePresentButObjectNotYetLoadedDoesNotResolve OK\n";
}

// Two direct-object candidates that BOTH individually pass every real
// check (their own dependentCheckFunctions() probe, and checkOneRelation()'s
// own per-pair relational probe against the one indirect candidate) must
// still produce a real ERR_AMBIG, not an arbitrary "first one wins" pick
// -- checkObjectRelations()'s own direct-object ambiguity branch,
// otherwise unexercised by the positive/negative tests above (both of
// which have exactly one genuinely valid pairing).
static void testParseObjTwoSingularObjectTokenRuleWithTwoValidDirectCandidatesProducesErrAmbig() {
    ObjectVarHarness harness;
    harness.writeFile("/unused.c",
        "void create() {}\n"
        "mixed parser_error_message(int errType, mixed obj, mixed extra) {\n"
        "    return ({ errType, obj, extra });\n"
        "}\n");
    assert(harness.objects.loadMasterObject());

    harness.writeFile("/po9c_room.c",
        "void setup() { parse_init(); }\n"
        "mixed *parse_command_id_list() { return ({\"room\"}); }\n"
        "int is_living() { return 0; }\n"
        "int inventory_accessible() { return 1; }\n"
        "int inventory_visible() { return 1; }\n");
    harness.writeFile("/po9c_sword.c",
        "void setup() { parse_init(); }\n"
        "void go(object dest) { move_object(dest); }\n"
        "mixed *parse_command_id_list() { return ({\"sword\"}); }\n"
        "int is_living() { return 0; }\n"
        "int inventory_accessible() { return 1; }\n"
        "int inventory_visible() { return 1; }\n"
        "int direct_put_obj_obj(object a, object b) { return 1; }\n");
    harness.writeFile("/po9c_chest.c",
        "void setup() { parse_init(); }\n"
        "void go(object dest) { move_object(dest); }\n"
        "mixed *parse_command_id_list() { return ({\"chest\"}); }\n"
        "int is_living() { return 0; }\n"
        "int inventory_accessible() { return 1; }\n"
        "int inventory_visible() { return 1; }\n"
        "int indirect_put_obj_obj(object a, object b) { return 1; }\n"); // accepts either sword
    harness.writeFile("/po9c_player.c",
        "void setup() { parse_init(); parse_add_rule(\"put\", \"OBJ OBJ\"); }\n"
        "void go(object dest) { move_object(dest); }\n"
        "mixed *parse_command_id_list() { return ({\"adventurer\"}); }\n"
        "int is_living() { return 1; }\n"
        "int inventory_accessible() { return 1; }\n"
        "int inventory_visible() { return 1; }\n"
        "int can_put_obj_obj(mixed a, mixed b) { return 1; }\n"
        "mixed run(string sentence) { return parse_sentence(sentence); }\n");

    auto room = harness.objects.cloneObject("/po9c_room");
    auto player = harness.objects.cloneObject("/po9c_player");
    auto sword1 = harness.objects.cloneObject("/po9c_sword");
    auto sword2 = harness.objects.cloneObject("/po9c_sword");
    auto chest = harness.objects.cloneObject("/po9c_chest");
    assert(room && player && sword1 && sword2 && chest);
    for (auto& ob : {room, player, sword1, sword2, chest}) harness.vm.callFunction(ob, "setup", {});
    harness.vm.callFunction(player, "go", std::vector<amlp::Value>{amlp::Value(room)});
    harness.vm.callFunction(sword1, "go", std::vector<amlp::Value>{amlp::Value(room)});
    harness.vm.callFunction(sword2, "go", std::vector<amlp::Value>{amlp::Value(room)});
    harness.vm.callFunction(chest, "go", std::vector<amlp::Value>{amlp::Value(room)});

    amlp::Value result =
        harness.vm.callFunction(player, "run", std::vector<amlp::Value>{amlp::Value(std::string("put sword chest"))});
    auto* arrPtr = std::get_if<std::shared_ptr<amlp::Array>>(&result.data);
    assert(arrPtr && *arrPtr && (*arrPtr)->items.size() == 3);
    assert(std::get<int64_t>((*arrPtr)->items[0].data) == 4); // ERR_AMBIG
    assert(std::get<int64_t>((*arrPtr)->items[1].data) == 0); // push_undefined() -> int 0
    auto* objArr = std::get_if<std::shared_ptr<amlp::Array>>(&(*arrPtr)->items[2].data);
    assert(objArr && *objArr && (*objArr)->items.size() == 2);
    assert(std::get<std::shared_ptr<amlp::LpcObject>>((*objArr)->items[0].data) == sword2);
    assert(std::get<std::shared_ptr<amlp::LpcObject>>((*objArr)->items[1].data) == sword1);

    std::cout << "testParseObjTwoSingularObjectTokenRuleWithTwoValidDirectCandidatesProducesErrAmbig OK\n";
}

// --- parse_my_rules(): row 0.13a's item 6 (the 8th and, as of this
// slice, final still-missing name from the original 8-function
// `parse_*` list -- parse_init/parse_refresh/parse_sentence/
// parse_add_rule/parse_add_synonym/parse_dump/parse_remove were each
// already implemented in earlier sessions). Real f_parse_my_rules()
// (packages/parser.c) is the same matching engine parse_sentence() uses,
// restricted two ways: an explicit `user` object stands in for
// this_player()/parse_user, and matching only considers rule nodes
// registered by the calling object (real parse_restricted). See
// ParserPackage::parseMyRules()'s own header comment for the full real
// derivation.

static void testParseMyRulesRestrictsMatchingToTheCallersOwnRegisteredRulesOnly() {
    std::string userSrc = "void setup() { parse_init(); }\n";
    auto user = compileProgramObject(userSrc);

    // objA and objB each register a rule under the exact same verb name,
    // but with incompatible grammar shapes (STR takes the whole rest of
    // the sentence; a lone WRD takes exactly one word). Only one of the
    // two shapes can ever match "hello there" (two leftover words) --
    // if parse_restricted were not actually enforced, calling from objB
    // could still reach objA's own STR rule and wrongly succeed.
    std::string srcA = "string resultA;\n"
                        "void setup() { parse_init(); parse_add_rule(\"zzzmyrule\", \"STR\"); }\n"
                        "int can_zzzmyrule_str(string s) { return 1; }\n"
                        "void do_zzzmyrule_str(string s) { resultA = s; }\n"
                        "mixed run(object u, string sentence) { return parse_my_rules(u, sentence, 1); }\n"
                        "string probe() { return resultA; }\n";
    std::string srcB = "string resultB;\n"
                        "void setup() { parse_init(); parse_add_rule(\"zzzmyrule\", \"WRD\"); }\n"
                        "int can_zzzmyrule_wrd(string s) { return 1; }\n"
                        "void do_zzzmyrule_wrd(string s) { resultB = s; }\n"
                        "mixed run(object u, string sentence) { return parse_my_rules(u, sentence, 1); }\n"
                        "string probe() { return resultB; }\n";
    auto objA = compileProgramObject(srcA);
    auto objB = compileProgramObject(srcB);

    amlp::Config config;
    amlp::ObjectManager objects(config);
    amlp::VM vm(objects, config);

    vm.callFunction(user, "setup", {});
    vm.callFunction(objA, "setup", {});
    vm.callFunction(objB, "setup", {});

    amlp::Value resultAVal = vm.callFunction(
        objA, "run", std::vector<amlp::Value>{amlp::Value(user), amlp::Value(std::string("zzzmyrule hello there"))});
    assert(std::get<int64_t>(resultAVal.data) == 1);
    assert(std::get<std::string>(vm.callFunction(objA, "probe", {}).data) == "hello there");
    // resultB was never assigned -- an uninitialized object variable
    // defaults to plain int 0 (LpcObject::LpcObject()'s own
    // Value(int64_t{0}) fill), not "".
    assert(std::get<int64_t>(vm.callFunction(objB, "probe", {}).data) == 0);

    amlp::Value resultBVal = vm.callFunction(
        objB, "run", std::vector<amlp::Value>{amlp::Value(user), amlp::Value(std::string("zzzmyrule hello there"))});
    assert(std::get<int64_t>(resultBVal.data) != 1);
    assert(std::get<int64_t>(vm.callFunction(objB, "probe", {}).data) == 0);

    std::cout << "testParseMyRulesRestrictsMatchingToTheCallersOwnRegisteredRulesOnly OK\n";
}

static void testParseMyRulesDefaultFlagReturnsVerbRuleArgsArrayWithoutCallingAnything() {
    std::string userSrc = "void setup() { parse_init(); }\n";
    auto user = compileProgramObject(userSrc);

    std::string handlerSrc =
        "int callCount;\n"
        "void setup() { parse_init(); parse_add_rule(\"zzzinspect\", \"STR\"); }\n"
        "int can_zzzinspect_str(string s) { return 1; }\n"
        "void do_zzzinspect_str(string s) { callCount++; }\n"
        // real "int flag = (st_num_arg == 3 ? (sp--)->u.number : 0);" --
        // the two-argument form's own real default is false, not true.
        "mixed run(object u, string sentence) { return parse_my_rules(u, sentence); }\n"
        "int probeCallCount() { return callCount; }\n";
    auto handler = compileProgramObject(handlerSrc);

    amlp::Config config;
    amlp::ObjectManager objects(config);
    amlp::VM vm(objects, config);

    vm.callFunction(user, "setup", {});
    vm.callFunction(handler, "setup", {});

    amlp::Value result = vm.callFunction(
        handler, "run", std::vector<amlp::Value>{amlp::Value(user), amlp::Value(std::string("Zzzinspect the widget"))});
    auto arr = std::get<std::shared_ptr<amlp::Array>>(result.data);
    // Same real "verb_rule" (try==3) shape already confirmed exactly by
    // testParseSentenceFallsBackToTheGenericDoVerbRuleNamingWhenTheSimpleNameIsNotDefined
    // -- make_function()'s own try==3 code path is shared, not
    // reimplemented per efun.
    assert(arr->items.size() == 5);
    assert(std::get<std::string>(arr->items[0].data) == "zzzinspect");
    assert(std::get<std::string>(arr->items[1].data) == "STR");
    assert(std::get<std::string>(arr->items[2].data) == "the widget");
    assert(std::get<std::string>(arr->items[3].data) == "Zzzinspect");
    assert(std::get<std::string>(arr->items[4].data) == "the widget");

    // Real code's own "give them the info for the wildcard call" branch
    // never invokes do_the_call() at all.
    assert(std::get<int64_t>(vm.callFunction(handler, "probeCallCount", {}).data) == 0);

    std::cout << "testParseMyRulesDefaultFlagReturnsVerbRuleArgsArrayWithoutCallingAnything OK\n";
}

static void testParseMyRulesRequiresParseInitOnBothTheUserAndTheCallingObject() {
    std::string userSrc = "void setup() { parse_init(); }\n";
    auto initedUser = compileProgramObject(userSrc);
    auto uninitUser = compileProgramObject(userSrc); // setup() never called

    std::string handlerSrc = "void setup() { parse_init(); }\n"
                              "int probe(object u) {\n"
                              "    if (!catch(parse_my_rules(u, \"whatever\", 1))) return 0;\n"
                              "    return 1;\n"
                              "}\n";
    auto initedHandler = compileProgramObject(handlerSrc);
    auto uninitHandler = compileProgramObject(handlerSrc); // setup() never called

    amlp::Config config;
    amlp::ObjectManager objects(config);
    amlp::VM vm(objects, config);

    vm.callFunction(initedUser, "setup", {});
    vm.callFunction(initedHandler, "setup", {});

    // real "(sp-2)->u.ob->pinfo" check -- the `user` argument itself
    // never called parse_init().
    assert(std::get<int64_t>(vm.callFunction(initedHandler, "probe", {amlp::Value(uninitUser)}).data) == 1);
    // real "current_object->pinfo" check -- the calling object itself
    // never called parse_init(), even though `user` did.
    assert(std::get<int64_t>(vm.callFunction(uninitHandler, "probe", {amlp::Value(initedUser)}).data) == 1);

    std::cout << "testParseMyRulesRequiresParseInitOnBothTheUserAndTheCallingObject OK\n";
}

static void testParseMyRulesRejectsARecursiveCallWhileOneIsAlreadyInProgress() {
    std::string userSrc = "void setup() { parse_init(); }\n";
    auto user = compileProgramObject(userSrc);

    std::string handlerSrc =
        "int nestedThrew;\n"
        "void setup() { parse_init(); parse_add_rule(\"zzzguard\", \"STR\"); }\n"
        "int can_zzzguard_str(string s) { return 1; }\n"
        // real "if (pi) error(\"Illegal to call parse_sentence()
        // recursively.\n\");" -- a parse_my_rules() call reached from
        // inside another one's own do_ callback must be rejected, unlike
        // parse_sentence()'s own matching guard, which real source
        // leaves commented out (ParseInProgressGuard's own comment).
        "void do_zzzguard_str(string s) {\n"
        "    if (catch(parse_my_rules(this_object(), \"zzzguard again\", 1))) nestedThrew = 1;\n"
        "}\n"
        "mixed run(object u, string sentence) { return parse_my_rules(u, sentence, 1); }\n"
        "int probeNestedThrew() { return nestedThrew; }\n";
    auto handler = compileProgramObject(handlerSrc);

    amlp::Config config;
    amlp::ObjectManager objects(config);
    amlp::VM vm(objects, config);

    vm.callFunction(user, "setup", {});
    vm.callFunction(handler, "setup", {});

    amlp::Value outer = vm.callFunction(
        handler, "run", std::vector<amlp::Value>{amlp::Value(user), amlp::Value(std::string("zzzguard hi there"))});
    // The outer call itself succeeds normally -- only the NESTED call
    // made from within its own do_ callback is rejected.
    assert(std::get<int64_t>(outer.data) == 1);
    assert(std::get<int64_t>(vm.callFunction(handler, "probeNestedThrew", {}).data) == 1);

    std::cout << "testParseMyRulesRejectsARecursiveCallWhileOneIsAlreadyInProgress OK\n";
}

// --- SIGPIPE (src/main.cpp, src/net/instruct.md's own "Known gap"
// note): a client connection closing at the wrong moment relative to
// this process's own next write() to that same socket used to be able
// to kill the *entire driver process*, not just that one connection --
// SIGPIPE's own default disposition is to terminate the process, and
// nothing in this codebase ever told the OS otherwise. Deterministically
// reproducible, unlike the crash-claim investigation two sessions before
// this one (which needed a live client and a running scheduler loop):
// closing one end of a connected socketpair and then writing to the
// other is the textbook, guaranteed way to raise SIGPIPE on any POSIX
// system, no timing race involved.
static void testSigpipeIsIgnoredSoAWriteAfterThePeerClosesDoesNotCrashTheProcess() {
    int fds[2];
    assert(::socketpair(AF_UNIX, SOCK_STREAM, 0, fds) == 0);
    amlp::Connection conn(fds[0]);
    ::close(fds[1]); // the peer disappears

    // Before main()'s own std::signal(SIGPIPE, SIG_IGN) (replicated at
    // the top of this file's own main(), since this test binary has its
    // own separate entry point -- see that call site's own comment),
    // this next line would have taken down this entire test process,
    // not just failed one assertion. Real Connection::send() already
    // tolerates a failed write() gracefully on its own (Connection.cpp:
    // "if (n < 0) { if (errno == EINTR) continue; break; }") -- it was
    // never Connection's own code that was missing anything, only the
    // process-wide signal disposition that decided whether send() ever
    // got the chance to run that handling at all.
    conn.send("this write must not kill the process");

    // Simply reaching this line, still running, is the real assertion:
    // proof the write above returned a normal -1/EPIPE instead of
    // delivering a fatal signal.
    assert(true);

    std::cout << "testSigpipeIsIgnoredSoAWriteAfterThePeerClosesDoesNotCrashTheProcess OK\n";
}

